// 中国編の会話の場面(story/cn_extract.py で台本から機械で抜き出したもの。ここは直接直さない)
const CN_SC={}, CN_DIR={};
CN_SC.c01_1=[{w:null,t:"第1話　上海"},{w:null,t:"ギリシャから東へ。三人で、飛行船の窓から雲の下を見ていた。"},{w:"elly",f:"surprised",t:"ねえ、下、ずっと海だよ。"},{w:"alek",f:"normal",t:"あと六時間。"},{w:"hero",f:"normal",t:"……竜って、ほんとにいるのかな。"},{w:"partner",t:"いなかったら、帰る。"},{w:"hero",f:"smile",t:"帰らない。"},{w:null,t:"ヤマトの端末が鳴った。東京の家からの画面通話だ。"},{w:"misaki",f:"normal",t:"ヤマト。夏休み、あと三日よ。",ph:1},{w:"hero",f:"normal",t:"……うん。"},{w:"misaki",f:"normal",t:"学校は画面の中なんだから、どこからでも出られるでしょ。",ph:1},{w:"misaki",f:"serious",t:"毎晩の連絡は、続けること。",ph:1},{w:"hana",t:"にいに、まだ帰らないの？",ph:1},{w:"hero",f:"smile",t:"竜を見てから。"},{w:"hana",t:"竜？　うそだ。",ph:1},{w:"misaki",f:"serious",t:"……それと。エンジュは、日本には入れないのよ。",ph:1},{w:"hero",f:"serious",t:"……分かってる。"},{w:"partner",t:"……うるさい家だ。"},{w:"hero",f:"angry",t:"聞こえてるって。"}];
CN_SC.c01_2=[{w:null,t:"飛行船が下りたのは、空にとどく塔が並ぶ街。上海。"},{w:null,t:"車も、店も、信号も、全部AIが動かしている。"},{w:"hero",f:"surprised",t:"すげえ……。ギリシャと、全然ちがう。"},{w:"elly",f:"surprised",t:"テリオンも、みんな首が光ってる。"},{w:"alek",f:"normal",t:"チップだ。街のAIと、全部つながってる。"},{w:"partner",t:"……うるさい街だ。"},{w:"x",n:"街の声",t:"ようこそ。ご用件をどうぞ。"},{w:"hero",f:"smile",t:"竜を、さがしてます。"},{w:"x",n:"街の声",t:"該当する生き物は、登録されていません。"},{w:"hero",f:"surprised",t:"……え。"},{w:"elly",f:"smile",t:"言われちゃったね。"}];
CN_SC.c01_3=[{w:null,t:"クロエ博士が連絡しておいてくれた、上海の研究所。"},{w:"lifa",f:"smile",t:"いらっしゃい。クロエ先輩の所の子たちね。リーファです。"},{w:"hero",f:"smile",t:"竜、いますか。"},{w:"lifa",f:"normal",t:"竜？　いないわよ。設計図も、完成したことないの。"},{w:"hero",f:"normal",t:"でも、ギリシャの王が、東の果てにいるって。"},{w:"lifa",f:"surprised",t:"王？　……古代テリオンの？　AIに聞いてみる。"},{w:"lifa",f:"smile",t:"「記録なし」。ほらね。"},{w:"alek",f:"normal",t:"……記録、それだけ？"},{w:"lifa",f:"serious",t:"AIが知らないなら、ないのよ。"},{w:"elly",f:"surprised",t:"……言い切った。"},{w:"lifa",f:"smile",t:"それより、街の勝負、やっていく？　ここの盤、石だらけよ。"},{w:"x",n:"都市の使い",t:"研究所のお客か。一回、相手してくれ。"},{w:"elly",f:"normal",t:"石ばっかりだと、エンジュの火、広がらないよ。"},{w:"hero",f:"serious",t:"じゃあ、まっすぐ当てる。"}];
CN_DIR.c01_3={"k": "勝負", "t": "都市の使い・盤＝石の街（荒地が多く、森がほとんどない）・覚えること＝石の街では、地の子が硬く、炎は燃え広がらない。森の少ない盤で、どこから撃つかを選ぶ。"};
CN_SC.c01_4w=[{w:"x",n:"都市の使い",t:"……やるな、外の子。"},{w:"hero",f:"smile",t:"硬いだけじゃん。"},{w:"lifa",f:"normal",t:"中国の子は、はじめから二段目の姿よ。"},{w:"hero",f:"surprised",t:"……ずるくない？"},{w:"lifa",f:"smile",t:"そっちの子も、二段目で出るの。"},{w:"lifa",f:"smile",t:"今夜は、研究所の客の部屋に泊まって。"},{w:"partner",t:"……ここ、においがしない。"},{w:"hero",f:"normal",t:"何の？"},{w:"partner",t:"土の。"}];
CN_SC.c01_4l=[{w:"x",n:"都市の使い",t:"石の上じゃ、うちの子は倒れないよ。"},{w:"alek",f:"normal",t:"硬いのを相手にするな。ほかを先に倒せ。"},{w:"lifa",f:"normal",t:"中国の子は、はじめから二段目の姿よ。"},{w:"hero",f:"surprised",t:"……ずるくない？"},{w:"lifa",f:"smile",t:"そっちの子も、二段目で出るの。"},{w:"lifa",f:"smile",t:"今夜は、研究所の客の部屋に泊まって。"},{w:"partner",t:"……ここ、においがしない。"},{w:"hero",f:"normal",t:"何の？"},{w:"partner",t:"土の。"}];
CN_SC.c01_5=[{w:null,t:"夜。研究所の客の部屋で、三人は寝そべっていた。"},{w:null,t:"急に、廊下の明かりが赤に変わった。"},{w:"x",n:"放送",t:"第七棟、警報。……訓練では、ありません。"},{w:"hero",f:"surprised",t:"え、なに？"},{w:null,t:"エンジュが、床に耳をつけた。"},{w:"partner",t:"……下で、何か鳴いてる。"},{w:null,t:"窓の下の路地を、白い影が一つ、すべるように走っていった。"},{w:"hero",f:"surprised",t:"……今の、何？"},{w:"alek",f:"normal",t:"見に行く気だろ。"},{w:"hero",f:"smile",t:"見に行く。"},{w:"elly",f:"sad",t:"……心配係、ここでも続くの？"},{w:null,t:"第1話　おわり"}];
CN_SC.c02_1=[{w:null,t:"第2話　裏通りの白い子"},{w:null,t:"三人で、研究所の裏の路地へ下りた。ごみの箱と、配達ロボットの列。"},{w:"hero",f:"normal",t:"さっきの、こっちに来たよな。"},{w:"elly",f:"surprised",t:"……いた。箱のかげ。"},{w:null,t:"白い、小さな子がうずくまっていた。頭に、短い角が二本。背中に、細いひれ。"},{w:"hero",f:"surprised",t:"……竜？"},{w:"alek",f:"normal",t:"いないって、言われたやつだな。"},{w:null,t:"首のチップが、赤くちかちか光っている。息が、早い。"},{w:"partner",t:"……薬のにおいがする。"},{w:"elly",f:"sad",t:"ふるえてる。熱、あるよ。"},{w:"hero",f:"normal",t:"おい。大丈夫か。"},{w:null,t:"竜の子は、ヤマトを見上げて、小さく鳴いた。それから、目を閉じた。"}];
CN_SC.c02_2=[{w:null,t:"路地の両はしに、ライトが立った。作業服の男たちと、空を飛ぶ機械。"},{w:"x",n:"ゼロデイの手下",t:"いたぞ！　第七棟の荷物だ！"},{w:"hero",f:"angry",t:"荷物じゃないだろ。"},{w:"x",n:"ゼロデイの手下",t:"ランサム様、見つけました。今、つかまえます。"},{w:"x",n:"ランサムの声",t:"手を出すな。おれが行く。"},{w:"x",n:"ゼロデイの手下",t:"え、でも、目の前に……。"},{w:"x",n:"ランサムの声",t:"おれがやると言った。"},{w:"x",n:"ゼロデイの手下",t:"……はい。……来るまで、見張っとくか。"},{w:"alek",f:"normal",t:"今のうちだ。抱えて走れ。"},{w:"hero",f:"serious",t:"エンジュ、前！"},{w:"elly",f:"normal",t:"この子、石の上だと、ちょっと元気になるよ。"}];
CN_DIR.c02_2={"k": "勝負", "t": "ゼロデイの手下と空飛ぶ機械・盤＝石の裏通り（荒地が多い）・覚えること＝逃げる盤。竜の子を連れて、盤の端の出口まで逃げきれば勝ち。竜は荒地で攻撃が上がる（`TYPE_TERR` の竜）。竜の子を前に出しすぎない。"};
CN_SC.c02_3w=[{w:null,t:"三人は、路地の角を三つ曲がって、川べりの橋の下に転がりこんだ。"},{w:"partner",t:"……追ってこない。"},{w:"elly",f:"sad",t:"……息、してる。"},{w:"hero",f:"normal",t:"軽いな、こいつ。"}];
CN_SC.c02_3l=[{w:"x",n:"ゼロデイの手下",t:"はい、行き止まり。"},{w:"x",n:"ランサムの声",t:"まだか！　何分かかってる！"},{w:"x",n:"ゼロデイの手下",t:"いや、手を出すなって……。"},{w:"x",n:"ランサムの声",t:"出せと言ってない！　見張れと言った！"},{w:"alek",f:"normal",t:"……今だ。"},{w:null,t:"手下たちが言い合っているすきに、三人は川べりの橋の下へ走った。"},{w:"elly",f:"sad",t:"……息、してる。"},{w:"hero",f:"normal",t:"軽いな、こいつ。"}];
CN_SC.c02_4=[{w:null,t:"アレクが、端末を竜の子の首に近づけた。チップの中身を読む。"},{w:null,t:"画面に、文字が出た。「所属　上海研究所　第七棟」"},{w:"alek",f:"serious",t:"……区分も出た。"},{w:null,t:"「区分　兵器　番号七〇二」"},{w:"elly",f:"surprised",t:"……兵器？"},{w:"hero",f:"angry",t:"こいつ、鼻水たらしてるのに？"},{w:"partner",t:"……かぜか。"},{w:"alek",f:"normal",t:"かぜの兵器は、聞いたことない。"},{w:null,t:"竜の子は、ヤマトの上着のすそを、ぎゅっとかんで眠っていた。"},{w:null,t:"第2話　おわり"}];
CN_SC.c03_1=[{w:null,t:"第3話　竹の森の村"},{w:null,t:"朝。橋の下で目をさますと、三人の前に、白い服の女の人が立っていた。"},{w:"lifa",f:"serious",t:"やっぱり、ここ。チップの信号、まだ出てるもの。"},{w:"hero",f:"angry",t:"……返さないぞ。"},{w:"lifa",f:"normal",t:"七〇二は、研究所の子よ。……一応、AIに聞くわ。"},{w:null,t:"リーファの端末に、文字が出た。「七〇二　処分予定」"},{w:"lifa",f:"surprised",t:"……処分？　そんな指示、見たことない。"},{w:"elly",f:"sad",t:"この子、まだ熱あるのに。"},{w:"lifa",f:"serious",t:"……研究所には、今は戻さない。"},{w:"lifa",f:"normal",t:"調べるまで、隠れてて。いい所があるの。"},{w:"alek",f:"normal",t:"どこ。"},{w:"lifa",f:"normal",t:"おばあちゃんの村。竹しかないけど。"}];
CN_SC.c03_2=[{w:null,t:"バスを二回乗りかえて、三人で、竹の海にかこまれた村に着いた。"},{w:"hero",f:"surprised",t:"……空が、緑だ。"},{w:"partner",t:"やっと、土のにおいだ。"},{w:null,t:"道場の門の前で、木の棒を持った男の子が、こっちをにらんでいた。"},{w:"hao",f:"angry",t:"……リーファ。また都市の人間を連れてきたのか。"},{w:"lifa",f:"angry",t:"おばあちゃんの家に来ただけよ。ハオには関係ない。"},{w:"hao",f:"angry",t:"AIの言いなりが、竹の村に何の用だ。"},{w:"lifa",f:"angry",t:"竹しか知らないくせに。"},{w:"elly",f:"surprised",t:"……この二人、いつもこう？"},{w:null,t:"村の人が、通りすがりに言った。「ちっちゃい時から、こうだよ」"},{w:"hao",f:"normal",t:"その狐。首、光ってないな。"},{w:"hero",f:"normal",t:"チップ、ない。"},{w:"hao",f:"smile",t:"……へえ。じゃあ、勝負だ。都市の子かどうか、見てやる。"},{w:"hero",f:"smile",t:"いいよ。"},{w:"elly",f:"normal",t:"ハオの子、森の子だよ。エンジュの火が効く。"},{w:"alek",f:"normal",t:"でも、ここは竹の中だ。森の子は、竹の中でよける。"}];
CN_DIR.c03_2={"k": "勝負", "t": "ハオ（カマコロ）・盤＝竹林（森が多い）・覚えること＝森の盤。炎は森で射程が伸び、燃え広がる。森の子は森でよけやすい。よけられる前に、広がる火で囲む。"};
CN_SC.c03_3w=[{w:"hao",f:"surprised",t:"……竹ごと、焼くなよ。"},{w:"hero",f:"smile",t:"焼いてない。ちょっとこげただけ。"},{w:"hao",f:"normal",t:"……都市の子じゃないのは、分かった。"},{w:"hao",f:"normal",t:"その白いの、何だ。"},{w:"hero",f:"normal",t:"竜。……たぶん。"},{w:"hao",f:"surprised",t:"竜？　師匠の昔話にしか、出てこないぞ。"}];
CN_SC.c03_3l=[{w:"hao",f:"smile",t:"竹の中じゃ、うちの子は当たらない。"},{w:"hero",f:"angry",t:"……どこにいたんだ、今。"},{w:"hao",f:"normal",t:"……都市の子じゃないのは、分かった。"},{w:"hao",f:"normal",t:"その白いの、何だ。"},{w:"hero",f:"normal",t:"竜。……たぶん。"},{w:"hao",f:"surprised",t:"竜？　師匠の昔話にしか、出てこないぞ。"}];
CN_SC.c03_4=[{w:null,t:"夜。竜の子は、土間の床に、おなかをぺたりとつけて眠っていた。"},{w:"hero",f:"normal",t:"寝相、悪いな。布団、あるのに。"},{w:"partner",t:"……地面に、くっついてる。"},{w:"hero",f:"normal",t:"なんで？"},{w:"partner",t:"腹で、音をさがしてる。……おれのとは、ちがう。"},{w:"elly",f:"normal",t:"……ふうん？"},{w:"lifa",f:"serious",t:"……チップの記録、半分、消されてる。"},{w:"hao",f:"normal",t:"だから言っただろ。機械は信用できない。"},{w:"lifa",f:"angry",t:"機械が勝手に消すわけないでしょ。だれかが消したの。"},{w:null,t:"その時、竹の森の向こうで、車のライトがいくつも光った。"},{w:"alek",f:"serious",t:"……村の外だ。三台。"},{w:null,t:"第3話　おわり"}];
CN_SC.c04_1=[{w:null,t:"第4話　師匠の口伝"},{w:null,t:"村の外の三台は、ライトを消して止まったままだった。"},{w:"alek",f:"serious",t:"動かない。見張ってるだけだ。"},{w:"hao",f:"angry",t:"都市の連中か。"},{w:"alek",f:"serious",t:"……車に、ゼロデイの印。"},{w:"lifa",f:"surprised",t:"……なんで、ゼロデイが。"},{w:null,t:"竜の子の首のチップが、急に赤く光った。"},{w:null,t:"竜の子は、床の上で体を丸めて、きゅう、と鳴いた。"},{w:"elly",f:"surprised",t:"どうしたの！？"},{w:"lifa",f:"serious",t:"合図よ。チップに、外から命令が入ってる。"},{w:"hero",f:"angry",t:"止めろよ、そんなの！"},{w:"lifa",f:"sad",t:"……ここからじゃ、止められない。"},{w:null,t:"しばらくして、光が消えた。竜の子は、ヤマトの足に頭をのせて動かなくなった。"},{w:"partner",t:"……寝ただけだ。"}];
CN_SC.c04_2=[{w:null,t:"朝。リーファが、持ってきた機械で、竜の子を調べていた。"},{w:"lifa",f:"serious",t:"この子、自分で熱を下げられない。体の設計が、半分しかないの。"},{w:"hero",f:"serious",t:"どうしたら治る。"},{w:"lifa",f:"normal",t:"もとにした設計図は、青龍。……古い言い伝えの竜よ。"},{w:"lifa",f:"serious",t:"その本物に会わないと、助からない。AIの答えも、同じ。"},{w:"alek",f:"normal",t:"竜は、いないんじゃなかったのか。"},{w:"lifa",f:"angry",t:"……設計図は、あるのよ。"},{w:"elly",f:"smile",t:"ねえ。この子、名前つけよう。"},{w:"hero",f:"smile",t:"白いから、シロ。"},{w:"elly",f:"normal",t:"犬じゃん。"},{w:"hao",f:"normal",t:"青龍の子なら、セイリュだろ。"},{w:"hero",f:"normal",t:"……それでいい。セイリュ。"},{w:null,t:"セイリュは、片目をあけて、またつぶった。"}];
CN_SC.c04_3=[{w:"hao",f:"normal",t:"青龍の話なら、師匠にきけ。ただし、勝ったらな。"},{w:"shifu",t:"道場の口伝は、門下か、わしに勝った者にしか言わん。"},{w:"hero",f:"smile",t:"じゃあ、勝つ。"},{w:"shifu",t:"門下になる方が、早いぞ。"},{w:"hero",f:"normal",t:"……勝つ方で。"},{w:"alek",f:"normal",t:"道場の床は、石だ。森の子でも、よけにくい。"}];
CN_DIR.c04_3={"k": "勝負", "t": "師範（カマケンとかまきり拳の子）・盤＝道場（遺跡の石の床）・覚えること＝今の手持ちで、中国の最初の古印の勝負。石の床では森の子もよけにくい。相手は勝負の中で進化してくる。"};
CN_SC.c04_4w=[{w:"shifu",t:"……ふむ。手のひらの子か。昔話でしか聞かん。"},{w:null,t:"師範は、竹の葉の形の飾りを、ヤマトの手にのせた。"},{w:null,t:"古印「竹の葉」を受け取った。"}];
CN_SC.c04_4l=[{w:"shifu",t:"まだ早い。もう一度、来い。"},{w:"hao",f:"smile",t:"師匠に一回で勝ったやつ、見たことない。"}];
CN_SC.c04_5=[{w:null,t:"師範は、目を閉じて、古い言葉を唱えはじめた。"},{w:null,t:"「ほー、ほー」と、呼ぶような音から始まる。"},{w:"elly",f:"surprised",t:"……今の始まり、おばあちゃんの歌と同じ。"},{w:"hao",f:"normal",t:"呼ぶところは、意味がないって、師匠は言ってる。"},{w:"elly",f:"surprised",t:"……うちも、そう言われた。"},{w:null,t:"唱え終わると、ハオが、普通の言葉で言いなおした。"},{w:"hao",f:"normal",t:"東の竜は、海の門の向こうで寝てる。"},{w:"hao",f:"normal",t:"門は、西と南と北の話を、全部合わせないと開かない。"},{w:"alek",f:"normal",t:"西の白虎、南の朱雀、北の玄武か。"},{w:"lifa",f:"surprised",t:"……AIの記録に、そんな話、ない。"},{w:"hao",f:"smile",t:"だろうな。"},{w:"hero",f:"serious",t:"じゃあ、三つ集めて、東へ行く。"},{w:"partner",t:"遠いぞ。"},{w:"hero",f:"normal",t:"セイリュ、軽いから平気。"}];
CN_SC.c04_6=[{w:null,t:"その時、竹の森の上を、ゼロデイの飛ぶ機械が何十も横切った。"},{w:null,t:"村の入口に、車が十台。まん中の車から、背の高い男が降りてきた。"},{w:"ransom",t:"ここか。……手下は下がってろ。おれ一人で十分だ。"},{w:"x",n:"ゼロデイの手下",t:"……昨日も、それで逃げられたんですけど。"},{w:"ransom",t:"昨日は、おれが行かなかったからだ。"},{w:null,t:"第4話　おわり"}];
CN_SC.c05_1=[{w:null,t:"第5話　竹林の夜"},{w:null,t:"村の入口で、ランサムが一人で、家を一軒ずつ見て回っていた。"},{w:"ransom",t:"……百軒ある。……全部、おれが見る。"},{w:"alek",f:"serious",t:"手下は下げたらしい。一人だ。"},{w:"hao",f:"normal",t:"竹の中の道なら、車は入れない。抜け道がある。"},{w:"hero",f:"normal",t:"セイリュ、起きろ。……起きないか。"},{w:"partner",t:"抱えていけ。"},{w:"lifa",f:"serious",t:"わたしも行く。第七棟のこと、調べたい。"},{w:"hao",f:"angry",t:"AIの言いなりが、ついてくるのか。"},{w:null,t:"リーファは、何も言わずに、端末の電源を切った。"},{w:"hao",f:"surprised",t:"……へえ。"},{w:"elly",f:"smile",t:"行こ。"}];
CN_SC.c05_2=[{w:null,t:"五人で、月の明かりだけをたよりに、竹の間の細い道を進んだ。"},{w:null,t:"前の方で、がさがさと竹がゆれた。"},{w:"patch",t:"ちょっと！　ほどいて！　髪が竹にからまってる！"},{w:"log",t:"おれは、服が。"},{w:"hero",f:"surprised",t:"……パッチとログ？"},{w:"patch",t:"あ。……ゼロデイのエリート、パッチ！　中国でも参上！"},{w:"alek",f:"normal",t:"ベラドンナは、つかまっただろ。"},{w:"patch",t:"だから今は、ランサム様の下なの！"},{w:"log",t:"上が、変わった。地図は、くれない。"},{w:"patch",t:"とにかく、その竜、置いていきなさい！"},{w:"hao",f:"normal",t:"……この二人、本当にゼロデイか？"},{w:"elly",f:"normal",t:"うん。いつも、こう。"},{w:"alek",f:"normal",t:"暗い。向こうの闇の子が、もやの中でよける。"}];
CN_DIR.c05_2={"k": "勝負", "t": "ログ＆パッチ・盤＝夜の竹林（暗い・森が多い）・覚えること＝夜の盤。暗い所（瘴気）では、闇の子がよけやすい。相手の闇の子が瘴気から出てきた所を、エンジュが森の上から撃つ（炎は森で射程+1）。"};
CN_SC.c05_3w=[{w:"patch",t:"……竹のせい！　今日は竹が悪い！"},{w:"log",t:"竹に言っても、聞かないぞ。"},{w:null,t:"二人が竹とけんかしている間に、五人は、竹林の西のはしまで走った。"}];
CN_SC.c05_3l=[{w:"patch",t:"はい、エリートの勝ち！　……あれ、竜は？"},{w:"log",t:"あっちの道へ、もう行った。"},{w:"patch",t:"なんで先に言わないの！"},{w:null,t:"二人が竹とけんかしている間に、五人は、竹林の西のはしまで走った。"}];
CN_SC.c05_4=[{w:null,t:"空が白くなってきた。竹林の外に、広い道が見える。"},{w:null,t:"道の上に、車が五台。ライトが、こっちを向いて止まった。"},{w:"hao",f:"surprised",t:"……先回りされた。"},{w:null,t:"先頭の車の屋根に、見覚えのある少年が立っていた。"},{w:"hero",f:"surprised",t:"……レン？"},{w:"alek",f:"serious",t:"ゼロデイの車だぞ。"},{w:"dimi",t:"その竜。……渡せ。"},{w:null,t:"第5話　おわり"}];
CN_SC.c06_1=[{w:null,t:"第6話　雷のトラ"},{w:"hero",f:"angry",t:"渡さない。……なんで、ゼロデイの車に乗ってんだよ。"},{w:"dimi",t:"関係ない。"},{w:"partner",t:"……あいつの横の子、においが変だ。"},{w:null,t:"レンのうしろの車から、手下たちが網の筒を持って降りてきた。"},{w:"hao",f:"serious",t:"西だ。高原まで走れば、道が広い。"},{w:"alek",f:"normal",t:"広い所は、こっちも丸見えだぞ。"},{w:"lifa",f:"serious",t:"……いい。高原なら、あてがある。"}];
CN_SC.c06_2=[{w:null,t:"竹林をぬけると、目の前に、草の高原がどこまでも広がっていた。"},{w:null,t:"五人で走る。うしろから、車の音と、空を飛ぶ機械の音。"},{w:"x",n:"ゼロデイの手下",t:"止まれ！　その竜は、うちの荷物だ！"},{w:"hero",f:"angry",t:"だから、荷物じゃない！"},{w:"elly",f:"normal",t:"ここ、平らだよ。風の子が速い。"},{w:"alek",f:"normal",t:"向こうの子、風だ。雷で落とせ。"},{w:"lifa",f:"serious",t:"ビリトラ、行ける？"}];
CN_DIR.c06_2={"k": "勝負", "t": "ゼロデイの手下（風の子と闇の子）・盤＝高原（平原が多い）・覚えること＝雷・風。平原では風の子が速い（移動+1）。雷は風に強い。リーファのビリトラを借りて、雷で風の子を先に落とす。"};
CN_SC.c06_3w=[{w:"x",n:"ゼロデイの手下",t:"くそっ、もう一台、呼べ！"},{w:null,t:"坂の向こうから、車がもう三台、上がってきた。"},{w:null,t:"リーファが、指を口に当てて、長く口笛を吹いた。"},{w:"hao",f:"surprised",t:"何してんだ。"},{w:"lifa",f:"normal",t:"呼んでるの。"},{w:null,t:"草の向こうで、何かが光った。一つ、二つ、十。"}];
CN_SC.c06_3l=[{w:"x",n:"ゼロデイの手下",t:"はい、そこまで。竜をよこせ。"},{w:null,t:"手下が、網の筒を向けた。"},{w:null,t:"リーファが、指を口に当てて、長く口笛を吹いた。"},{w:"hao",f:"surprised",t:"何してんだ。"},{w:"lifa",f:"normal",t:"呼んでるの。"},{w:null,t:"草の向こうで、何かが光った。一つ、二つ、十。"}];
CN_SC.c06_4=[{w:null,t:"稲妻の模様のトラが、群れで走ってきた。体じゅうで、ぱちぱちと雷が鳴っている。"},{w:"x",n:"ゼロデイの手下",t:"な、なんだ、あれ！"},{w:null,t:"群れが手下の車のまわりを走ると、車のライトが全部消えた。"},{w:"x",n:"ゼロデイの手下",t:"電気が……！　撤収、撤収！"},{w:null,t:"一番大きなトラが、レンの車の前で立ち止まった。"},{w:"dimi",t:"……今日はいい。"},{w:null,t:"レンの車も、手下の車のあとを追って、東へ戻っていった。"},{w:"hero",f:"surprised",t:"……リーファさんの子？"},{w:"lifa",f:"smile",t:"研究所の観測所で育てた群れ。わたしが世話係だったの。"},{w:null,t:"小さなビリトラが一体、リーファの足に頭をこすりつけた。"},{w:"hao",f:"normal",t:"……AIの研究所の子が、口笛で来るのか。"},{w:"lifa",f:"normal",t:"来るわよ。毎朝、口笛でごはんだったから。"},{w:"hao",f:"normal",t:"……ふーん。"}];
CN_SC.c06_5=[{w:null,t:"夕方。群れの長の大きなトラが、一頭だけ、北の岩山を見上げていた。"},{w:"partner",t:"……あいつ、岩の上を見てる。"},{w:null,t:"岩の上に、苔におおわれた、小さな古い祠があった。"},{w:"hao",f:"surprised",t:"……白虎の岩だ。師匠の口伝に出てくる。"},{w:"alek",f:"normal",t:"西のかけらか。"},{w:null,t:"長のトラは、低く一声鳴くと、岩山の方へ歩きだした。"},{w:null,t:"第6話　おわり"}];
CN_SC.c07_1=[{w:null,t:"第7話　白虎の岩"},{w:null,t:"五人で、岩山を登った。てっぺんの祠の前に、大きな白い石が一つ。"},{w:"elly",f:"surprised",t:"石……じゃない。これ、寝てる。"},{w:null,t:"白い石に見えたのは、体を丸めた、大きな白い虎だった。"},{w:"hao",f:"surprised",t:"……白虎だ。師匠の昔話の。"},{w:"hero",f:"smile",t:"でっか……。"},{w:"partner",t:"起きないぞ。"},{w:"hao",f:"normal",t:"口伝で、呼ぶところがある。……やってみる。"},{w:null,t:"ハオが、古い発音で唱えはじめた。「ほー、ほー」と呼ぶ音から。"},{w:null,t:"エリーが、同じ音を、少しおくれて重ねた。"},{w:null,t:"白い虎の耳が、ぴくりと動いた。"}];
CN_SC.c07_2=[{w:null,t:"虎が、ゆっくり頭を上げた。体のまわりに、細い雷が走る。"},{w:null,t:"虎は、子どもたちの顔を順に見て、最後にセイリュを見た。"},{w:null,t:"大人のリーファの方には、一度も顔を向けなかった。"},{w:null,t:"低い声で、古い言葉を一言だけ言った。"},{w:"elly",f:"normal",t:"……ハオ、今の、分かる？"},{w:"hao",f:"normal",t:"「東の子か」……だと思う。"},{w:"elly",f:"normal",t:"ほー、ほーの後ろ、何か言ってたよね。"},{w:"hao",f:"normal",t:"……呼ぶ所の後ろに、一句ある。師匠も、意味は知らん。"},{w:"lifa",f:"surprised",t:"……ボルケン。本物の、古代テリオン。"},{w:null,t:"その時、岩山の下で、車のドアが次々に開く音がした。"},{w:"x",n:"ゼロデイの手下",t:"いたぞ！　岩の上だ！"},{w:"alek",f:"serious",t:"昨日の続きだ。数が多い。"},{w:null,t:"白い虎が、のそりと立ち上がり、ヤマトの横に並んだ。"},{w:"hero",f:"surprised",t:"……手伝ってくれるの？"},{w:"partner",t:"邪魔するなよ、でかいの。"}];
CN_DIR.c07_2={"k": "勝負", "t": "ゼロデイの追っ手（手下たち）・盤＝白虎の岩（荒地の岩山）・覚えること＝古代テリオンと並んで戦う。ボルケン（雷）が味方に一体入る。強い味方に頼りきらず、ボルケンが雷を落とせる所へ相手を集める。"};
CN_SC.c07_3w=[{w:"x",n:"ゼロデイの手下",t:"車に戻れ！　あの虎、話がちがう！"},{w:"partner",t:"でかいの、まあまあだな。"},{w:null,t:"手下たちの車は、土ぼこりを上げて、山の下へ逃げていった。"}];
CN_SC.c07_3l=[{w:null,t:"押しこまれた時、ボルケンが一声ほえた。岩山じゅうに雷が落ちた。"},{w:"x",n:"ゼロデイの手下",t:"む、無理だ！　下がれ！"},{w:null,t:"手下たちの車は、土ぼこりを上げて、山の下へ逃げていった。"}];
CN_SC.c07_4=[{w:null,t:"ボルケンは、祠の石を前足でこすった。苔の下から、古い字が出てきた。"},{w:"lifa",f:"normal",t:"……読むだけ。"},{w:null,t:"リーファは、切っていた端末の電源を入れた。端末が、石の字を読み上げる。"},{w:null,t:"「西の一句　虎は、朝の来る方へ吠える」"},{w:"alek",f:"normal",t:"これが、西のかけらか。"},{w:"hao",f:"surprised",t:"……師匠の言ってた、西の話だ。"},{w:"hero",f:"normal",t:"朝の来る方って、東だろ。"},{w:"hao",f:"angry",t:"……東なのは、分かってる。で、東のどこだよ。"},{w:"elly",f:"smile",t:"……海？"}];
CN_SC.c07_5=[{w:null,t:"ボルケンは、南の空を見上げて、もう一度、古い言葉を言った。"},{w:"hao",f:"serious",t:"「南の鳥は、もう別の子を見てる」……たぶん。"},{w:"hero",f:"surprised",t:"別の子？"},{w:null,t:"ボルケンは答えずに、また体を丸めた。白い石に戻ったように、動かなくなった。"},{w:"partner",t:"……寝た。"},{w:null,t:"第7話　おわり"}];
CN_SC.c08_1=[{w:null,t:"第8話　止まった街"},{w:null,t:"南へ向かう列車は、上海の駅から出る。五人は、もう一度、上海へ戻った。"},{w:"lifa",f:"serious",t:"ついでに、研究所の第七棟の記録を見たい。"},{w:"hao",f:"angry",t:"また機械の街か。"},{w:"alek",f:"normal",t:"南へ行く列車は、ここからしか出ない。"},{w:"hero",f:"normal",t:"セイリュ、街だぞ。"},{w:null,t:"セイリュは、ヤマトの上着の中で、ちらりと目をあけた。"}];
CN_SC.c08_2=[{w:null,t:"駅前の広い通り。そのとたん、街じゅうの信号が、いっせいに赤になった。"},{w:null,t:"車が止まる。店の扉が閉まる。空の案内の画面が、全部まっ黒になった。"},{w:"x",n:"街の声",t:"……アークとの接続が、切れました。……ようこそ。"},{w:"elly",f:"surprised",t:"な、なに？"},{w:null,t:"通りのテリオンたちの首のチップが、赤く光りだした。"},{w:null,t:"配達の鳥が荷物を落とす。番の犬の子が、主にうなる。"},{w:null,t:"ヤマトの上着の中で、セイリュの首も、赤く光った。セイリュが、きゅう、と鳴いた。"},{w:null,t:"ビリトラの首も光った。リーファは黙って、ビリトラを抱き上げた。"},{w:"alek",f:"normal",t:"……うちの子は、光らないな。"},{w:"lifa",f:"serious",t:"ギリシャの研究所の登録だもの。止まるのは、この街の子だけ。"},{w:"lifa",f:"surprised",t:"……上海のアークが、乗っ取られてる？"},{w:"hao",f:"angry",t:"ほら見ろ。"},{w:"lifa",f:"angry",t:"……確かめてから言う。"},{w:null,t:"リーファは、街の柱の古い点検口を、手でこじあけた。"},{w:"alek",f:"normal",t:"……AIに聞かないのか。"},{w:"lifa",f:"serious",t:"今は、聞いてもうそを言うかもしれない。"}];
CN_SC.c08_3=[{w:null,t:"通りのまん中で、赤く光る子たちが、逃げおくれた人を囲んでいた。"},{w:"hero",f:"serious",t:"エンジュ、行くぞ。"},{w:"partner",t:"……あいつら、目が変だ。"},{w:"elly",f:"normal",t:"倒さないで！　あの子たち、操られてるだけ！"},{w:"lifa",f:"serious",t:"動きを止めてくれたら、ここからチップを切れる。"}];
CN_DIR.c08_3={"k": "勝負", "t": "乗っ取られた街の子たち・盤＝石の街（荒地が多い）・覚えること＝チップの乗っ取り。乗っ取られた子は、まわりの人をねらう。人のそばの子から先に止める。止めた子は、リーファがチップを切る。"};
CN_SC.c08_4w=[{w:null,t:"止まった子の首から、赤い光が一つずつ消えていった。"},{w:"lifa",f:"smile",t:"切れた。……みんな、ただ眠ってるだけ。"},{w:null,t:"セイリュとビリトラの首の光も、消えた。"},{w:null,t:"点検口の中の古い画面に、一行だけ、命令の出どころが出ていた。"},{w:"lifa",f:"serious",t:"「ゼロデイ」。……第七棟と、同じ印。"},{w:"hao",f:"normal",t:"……で、確かめたら、どうなんだ。"},{w:"lifa",f:"angry",t:"あんたの言うとおりよ。今日だけは。"},{w:"hao",f:"smile",t:"今日だけかよ。"}];
CN_SC.c08_4l=[{w:null,t:"何体かが、通りの向こうへ走っていった。"},{w:"lifa",f:"sad",t:"……全部は、無理だった。"},{w:null,t:"セイリュとビリトラの首の光も、消えた。"},{w:null,t:"点検口の中の古い画面に、一行だけ、命令の出どころが出ていた。"},{w:"lifa",f:"serious",t:"「ゼロデイ」。……第七棟と、同じ印。"},{w:"hao",f:"normal",t:"……で、確かめたら、どうなんだ。"},{w:"lifa",f:"angry",t:"あんたの言うとおりよ。今日だけは。"},{w:"hao",f:"smile",t:"今日だけかよ。"}];
CN_SC.c08_5=[{w:null,t:"駅の上の陸橋から、広場の向こうのビルの屋上が見えた。"},{w:null,t:"屋上に、二人。背の高い男と、肩にカブトムシの子をのせた少年。"},{w:"hero",f:"surprised",t:"……レンと、ランサム？"},{w:null,t:"ランサムが、黒い箱をレンに渡した。レンは、ふたを少しだけあけて、閉じた。"},{w:"alek",f:"serious",t:"……取り引きだ。"},{w:"partner",t:"あの箱、さっきの赤い光と同じにおいがする。"},{w:null,t:"第8話　おわり"}];
CN_SC.c09_1=[{w:null,t:"第9話　火の山"},{w:null,t:"南へ向かう列車を降りると、地面が赤かった。崖から、大きな骨がのぞいている。"},{w:"hero",f:"surprised",t:"……恐竜の骨？"},{w:"lifa",f:"smile",t:"竜の骨って、昔の人は呼んでたの。だから竜の言い伝えが残った。"},{w:"hao",f:"normal",t:"じゃあ、竜はいなかったってことか。"},{w:"lifa",f:"normal",t:"……セイリュがいるから、その話は今、むずかしい。"},{w:null,t:"セイリュは、ヤマトの上着の中で、暑そうに舌を出していた。"},{w:"partner",t:"ここ、いい。地面があったかい。"}];
CN_SC.c09_2=[{w:null,t:"谷の奥に、煙を上げる山がそびえていた。坂の道の横を、赤い溶岩が流れている。"},{w:"alek",f:"serious",t:"足あとだ。カブトムシの子と、少年の靴。"},{w:"elly",f:"surprised",t:"レン、ここ登ったの？"},{w:"alek",f:"normal",t:"半日前だな。先に行ってる。"},{w:"hero",f:"angry",t:"あいつ、どこ行く気だ。"},{w:"hao",f:"normal",t:"南の鳥の山へ行くなら、この坂がいちばん近い。"},{w:null,t:"坂の上から、作業服の男たちが下りてきた。肩に、網の筒。"},{w:"x",n:"ゼロデイの手下",t:"またガキか。……竜は、置いていけ。"},{w:"elly",f:"normal",t:"ここ、溶岩のそばだよ。エンジュは強いけど、氷の子は弱る。"},{w:"alek",f:"normal",t:"向こうは氷の子を連れてる。溶岩の上に立たせろ。"}];
CN_DIR.c09_2={"k": "勝負", "t": "ゼロデイの手下・盤＝火の山の坂（溶岩の流れる坂）・覚えること＝溶岩。溶岩の上では炎と竜が強い（攻撃が上がる）。氷の子は溶岩で弱る。相手の氷の子を溶岩の上へ誘う。"};
CN_SC.c09_3w=[{w:"x",n:"ゼロデイの手下",t:"あつっ、あっつ！　撤収！"},{w:"partner",t:"溶岩の上なら、負けない。"},{w:null,t:"手下たちは、坂の下の車へ走っていった。五人は、火口の手前まで登った。"}];
CN_SC.c09_3l=[{w:"x",n:"ゼロデイの手下",t:"熱いのは、こっちも同じだ。"},{w:"hao",f:"angry",t:"……こいつら、しつこいな。"},{w:null,t:"手下たちは、坂の下の車へ走っていった。五人は、火口の手前まで登った。"}];
CN_SC.c09_4=[{w:null,t:"山の上から、南の方に、もう一つ、とがった峰が見えた。"},{w:"lifa",f:"normal",t:"あれが、南の峰。言い伝えの鳥の山。"},{w:null,t:"セイリュが、上着から顔を出して、南の峰をじっと見た。"},{w:"hero",f:"normal",t:"セイリュ、あっち、気になるのか。"},{w:null,t:"その時、南の峰のてっぺんが、ぽっと赤く光った。"},{w:null,t:"光は、見る見るうちに大きくなり、峰の頂が、火の色にゆれはじめた。"},{w:"hao",f:"surprised",t:"……山頂が、燃えてる。"},{w:"alek",f:"serious",t:"レンが、先に着いたんだ。"},{w:null,t:"第9話　おわり"}];
CN_SC.c10_1=[{w:null,t:"第10話　南の峰"},{w:null,t:"夜明け前。五人で、南の峰の細い道を登った。頂の火は、まだゆれている。"},{w:"partner",t:"……熱くない火だ。"},{w:"hero",f:"surprised",t:"え？"},{w:"partner",t:"燃えてるのに、においがしない。"}];
CN_SC.c10_2=[{w:null,t:"頂の岩の上に、火の輪が、ゆっくり回っていた。中は空っぽだ。"},{w:null,t:"火の輪から少しはなれた岩に、レンが一人で座っていた。"},{w:null,t:"レンは、端末の画面を見ていた。"},{w:null,t:"画面には、男の人と、小さいころのレン。二人で、盤をはさんで笑っている。"},{w:null,t:"足音に気づいて、レンは端末をポケットにしまった。"},{w:"dimi",t:"……遅い。"},{w:"hero",f:"normal",t:"レン。その火、何。"},{w:"dimi",t:"知らない。来たら、もう燃えてた。"},{w:null,t:"その時、峰の下から、空を飛ぶ機械の音が近づいてきた。"},{w:"x",n:"ゼロデイの手下",t:"いたぞ！　火の鳥が出る前に、網をかけろ！"},{w:"hao",f:"angry",t:"鳥はまだ出てないだろ。"},{w:"x",n:"ゼロデイの手下",t:"出てから網を出したら、遅いんだよ！"},{w:"dimi",t:"……おれは、やらない。"},{w:"alek",f:"normal",t:"見てるだけか。……来るぞ。"}];
CN_DIR.c10_2={"k": "勝負", "t": "ゼロデイの手下・盤＝南の峰の頂（岩場・荒地が多い）・覚えること＝岩の上の勝負。荒地では地の子が硬く、竜が強い（相手の地の子は後回しにする）。レンは手伝わない（盤に出ない）。"};
CN_SC.c10_3w=[{w:"x",n:"ゼロデイの手下",t:"くっ……。一回、下がる！"},{w:null,t:"手下たちは、峰の下へ引いていった。"},{w:"hao",f:"normal",t:"エリー。口伝の呼ぶところ、いっしょにやるぞ。"},{w:"elly",f:"normal",t:"うん。"}];
CN_SC.c10_3l=[{w:"x",n:"ゼロデイの手下",t:"どけ、ガキ。網をかけるぞ。"},{w:null,t:"網の筒が、火の輪に向いた。"},{w:"hao",f:"normal",t:"エリー。口伝の呼ぶところ、いっしょにやるぞ。"},{w:"elly",f:"normal",t:"うん。"}];
CN_SC.c10_4=[{w:null,t:"ハオが古い発音で唱える。エリーが「ほー、ほー」と重ねる。"},{w:null,t:"火の輪が、一気にふくらんだ。輪の中から、赤と金の羽が広がる。"},{w:null,t:"大きな火の鳥が、頂の上に浮かんだ。"},{w:"hero",f:"surprised",t:"……出た。"},{w:"lifa",f:"surprised",t:"朱雀……。"},{w:null,t:"網の筒が、また火の鳥に向いた。火の鳥がひと羽ばたきすると、筒が全部、灰になった。"},{w:"x",n:"ゼロデイの手下",t:"む、無理！　撤収！"},{w:null,t:"火の鳥は、五人の上を一回まわった。セイリュを見て、エリーを見て、ハオを見た。"},{w:null,t:"それから、すっと横へ流れて、岩の上のレンの前に下りた。"},{w:"hero",f:"surprised",t:"……え。そっち？"},{w:"hao",f:"angry",t:"起こしたの、おれたちだぞ。"},{w:null,t:"火の鳥が、レンに向かって、短く鳴いた。古い言葉だった。"},{w:"hao",f:"normal",t:"……「取り返しに来た子か」。……たぶん。"},{w:"dimi",t:"…………。"},{w:null,t:"レンは、ポケットの上から、端末をにぎった。何も言わなかった。"}];
CN_SC.c10_5=[{w:null,t:"火の鳥の羽の光が、頂の大きな石を照らした。石の面に、古い字が浮かぶ。"},{w:"lifa",f:"surprised",t:"字！　ちょっと待って、今……。"},{w:null,t:"リーファが端末を向けた時、光が消えた。字も、見えなくなった。"},{w:"lifa",f:"sad",t:"……撮れなかった。"},{w:"alek",f:"normal",t:"見えた。覚えた。"},{w:"elly",f:"surprised",t:"え、あの一瞬で？"},{w:"alek",f:"normal",t:"「鳥は、海の上で輪を描く」。"},{w:"hao",f:"normal",t:"……おまえ、何者だ。"},{w:"alek",f:"normal",t:"案内役だ。"}];
CN_SC.c10_6=[{w:null,t:"レンは、何も言わずに立ち上がり、峰の下へ歩きだした。"},{w:null,t:"火の鳥は、その頭の上を、ゆっくり回りながらついていった。"},{w:"hero",f:"normal",t:"……さっき、レン、写真見てた。"},{w:"elly",f:"normal",t:"……うん。"},{w:null,t:"峰の下で、ゼロデイの車のドアが開いて、閉じた。"},{w:null,t:"火の鳥は、車の上を、まだ回っていた。"},{w:null,t:"第10話　おわり"}];
CN_SC.c11_1=[{w:null,t:"第11話　追っ手のレン"},{w:null,t:"山のふもとの古い町。川ぞいの石の道を、五人で北へ歩いていた。"},{w:"hao",f:"normal",t:"北の駅から、東へ行く列車が出てる。それに乗る。"},{w:"lifa",f:"serious",t:"セイリュ、ゆうべから、せきが止まらない。"},{w:null,t:"セイリュが、ヤマトの上着の中で、小さくせきをした。"},{w:"hero",f:"normal",t:"……駅まで、もうちょっとだからな。"},{w:"partner",t:"うしろ。来てる。"}];
CN_SC.c11_2=[{w:null,t:"川の橋の向こうに、ゼロデイの車が三台。まん中に、レンが立っていた。"},{w:null,t:"レンの頭の上を、火の鳥がゆっくり回っている。"},{w:"dimi",t:"竜を渡せ。"},{w:"hero",f:"angry",t:"渡さない。"},{w:"dimi",t:"ランサムとの約束だ。"},{w:"alek",f:"normal",t:"……約束、ね。"},{w:"x",n:"ゼロデイの手下",t:"おい、その鳥、使えよ。でかい火で一発だろ。"},{w:"dimi",t:"……こいつは、言うこと聞かない。"},{w:"x",n:"ゼロデイの手下",t:"じゃあ、なんで連れてるんだよ。"},{w:"dimi",t:"連れてない。ついてくるんだ。"},{w:"hao",f:"surprised",t:"……鳥、つかまえ損ねてるだけじゃないか。"},{w:"alek",f:"serious",t:"レンは強い。まともにやるな。駅まで逃げろ。"}];
CN_DIR.c11_2={"k": "勝負", "t": "レンとゼロデイの手下・盤＝川ぞいの道（水辺と橋）・覚えること＝強い相手から逃げる。倒しに行かない。橋をわたって、駅の側の出口まで逃げきれば勝ち。水辺では、水の子が速い（移動+1）。相手の水の子に先回りされる前に、橋を渡る。"};
CN_SC.c11_3w=[{w:null,t:"五人は、橋を渡りきった。車は、橋のたもとで立ち往生している。"},{w:"x",n:"ゼロデイの手下",t:"回れ！　次の橋だ！"},{w:"dimi",t:"……遅い。"},{w:null,t:"火の鳥は、一度も火を吐かなかった。"}];
CN_SC.c11_3l=[{w:null,t:"カブトムシの子の角が、エンジュを橋のらんかんに押しつけた。"},{w:"x",n:"ゼロデイの手下",t:"よし、竜を取れ！"},{w:null,t:"その時、火の鳥が、レンの目の前に、すっと下りた。"},{w:"x",n:"ゼロデイの手下",t:"……え、なんでそこ？"},{w:"dimi",t:"……どけ。"},{w:null,t:"火の鳥は動かない。レンは、前へ出られない。そのすきに、五人は駅の方へ走った。"},{w:null,t:"火の鳥は、一度も火を吐かなかった。"}];
CN_SC.c11_4=[{w:null,t:"北の駅のホームに、五人で駆けこんだ。人はいない。"},{w:"elly",f:"sad",t:"……列車、ない。"},{w:"lifa",f:"normal",t:"時刻表、見てくる。"},{w:null,t:"その時、線路がかすかにふるえた。"},{w:null,t:"線路の先、霧の向こうから、白い高速列車の顔が近づいてきた。"},{w:"hao",f:"surprised",t:"……止まらないやつだ、あれ。"},{w:"hero",f:"serious",t:"……乗る。"},{w:"alek",f:"surprised",t:"どうやって。"},{w:null,t:"第11話　おわり"}];
CN_SC.c12_1=[{w:null,t:"第12話　列車の中"},{w:null,t:"高速列車は、ホームの横で、ほんの少しだけ速さを落とした。"},{w:"lifa",f:"surprised",t:"点検で、ここだけゆっくり通るの！　今！"},{w:null,t:"五人は、開いていた荷物の扉に、順番に飛びこんだ。"},{w:"hao",f:"angry",t:"……今の、時刻表に書いてあったのか。"},{w:"lifa",f:"normal",t:"ちがう。勘。"},{w:"hao",f:"angry",t:"勘かよ！"}];
CN_SC.c12_2=[{w:null,t:"荷物の車両から客車へ。乗っているのは、眠っている人ばかりだった。"},{w:null,t:"セイリュが、ヤマトの腕の中で、ぐったりしていた。体が熱い。"},{w:"elly",f:"sad",t:"さっきより、熱い。"},{w:"lifa",f:"serious",t:"冷やすもの、ある？"},{w:"hero",f:"normal",t:"……エンジュ、冷たいもの出せる？"},{w:"partner",t:"出せるわけないだろ。"},{w:null,t:"ハオが、売り子の台から氷の袋を一つ取って、黙って代金を置いた。"},{w:"lifa",f:"surprised",t:"……ありがとう。"},{w:"hao",f:"normal",t:"竜の分だ。"},{w:null,t:"セイリュは、氷の袋に、おなかをぺたりとつけた。"}];
CN_SC.c12_3=[{w:null,t:"アレクの端末に、短い文が届いた。案内役の仲間からだ。"},{w:"alek",f:"serious",t:"……レンの父親のこと、聞いておいた。"},{w:"elly",f:"surprised",t:"いつのまに。"},{w:"alek",f:"normal",t:"……ギリシャの案内の仲間に、聞いた。"},{w:null,t:"「レンの父　アークの技師。三年前の大停電で、責任者として名前が出た」"},{w:"lifa",f:"surprised",t:"三年前……。……あの、大きな停電？"},{w:"hao",f:"normal",t:"それと、レンがゼロデイにいるのと、関係あるのか。"},{w:"alek",f:"normal",t:"まだ、うわさだ。確かめてない。"},{w:null,t:"ヤマトは、何も言わずに、窓の外の暗い山を見ていた。"}];
CN_SC.c12_4=[{w:null,t:"前の車両の扉が開いた。作業服の男が二人、通路をふさぐように立った。"},{w:"x",n:"ゼロデイの手下",t:"駅で乗ったの、見てたぞ。竜を出せ。"},{w:"alek",f:"normal",t:"通路だ。横に並べない。一体ずつだ。"},{w:"elly",f:"normal",t:"前の子が倒れたら、すぐ次！"}];
CN_DIR.c12_4={"k": "勝負", "t": "ゼロデイの手下・盤＝列車の通路（細長い狭い盤）・覚えること＝狭い盤。横に並べないので、前に出る一体と、うしろから届く子の組み合わせを考える。射程の長い子をうしろに。"};
CN_SC.c12_5w=[{w:"x",n:"ゼロデイの手下",t:"せ、狭すぎる……！"},{w:"partner",t:"狭いのは、おまえらも同じだ。"},{w:null,t:"手下たちは、前の車両へ逃げていった。客車に、静けさが戻った。"}];
CN_SC.c12_5l=[{w:"x",n:"ゼロデイの手下",t:"はい、そこまで。"},{w:null,t:"手下が手をのばした時、列車が大きくゆれた。手下は、座席に頭からつっこんだ。"},{w:"hao",f:"smile",t:"……今だ。"},{w:null,t:"手下たちは、前の車両へ逃げていった。客車に、静けさが戻った。"}];
CN_SC.c12_6=[{w:null,t:"セイリュが、氷の袋の上で、うっすら目をあけた。天井を見ている。"},{w:null,t:"ごとん。ごとん。天井の上で、重い足音がした。"},{w:"partner",t:"……上だ。"},{w:"alek",f:"serious",t:"走ってる列車の、屋根の上か。"},{w:"hero",f:"serious",t:"……だれだよ。"},{w:null,t:"第12話　おわり"}];
CN_SC.c13_1=[{w:null,t:"第13話　列車の屋根"},{w:null,t:"客車のはしの点検口から、ヤマトとエンジュが屋根へ出た。風が、顔をたたく。"},{w:"alek",f:"serious",t:"待て、一人で行くな！"},{w:"hero",f:"angry",t:"すぐ戻る！"},{w:null,t:"屋根の上に、レンが立っていた。足もとに、黒い角の子が一体。"},{w:"dimi",t:"……遅い。"},{w:"hero",f:"angry",t:"またそれかよ。"},{w:null,t:"黒い角の子の首で、赤い光が、ちかちか光っている。"},{w:"partner",t:"……あいつ、薬のにおいしかしない。"},{w:"dimi",t:"ランサムからもらった。"},{w:null,t:"レンの頭の上の空で、火の鳥が、ゆっくり回っていた。"},{w:null,t:"うしろの点検口から、エリーとアレクも上がってきた。セイリュを抱えたまま。"},{w:"elly",f:"sad",t:"ヤマト！　セイリュ、置いてこられなかった！"},{w:"alek",f:"serious",t:"下にも手下が来た。下も上も同じだ。"}];
CN_DIR.c13_1={"k": "勝負", "t": "レンと黒い角の子・盤＝列車の屋根（細長い狭い盤）・覚えること＝負け戦。勝てない相手もいる。倒れる前に、守る子（セイリュ）から相手を遠ざける。"};
CN_SC.c13_2w=[{w:null,t:"黒い角の子が倒れた。……と思ったら、何もなかったように立ち上がった。"},{w:"elly",f:"surprised",t:"うそ……！"},{w:null,t:"黒い角の子が、まっすぐセイリュの方へ走った。"},{w:"hero",f:"angry",t:"エンジュ！"},{w:null,t:"エンジュが、セイリュとエリーの前に飛びこんだ。"},{w:null,t:"角が、エンジュの体を、屋根のはしまではじき飛ばした。"},{w:null,t:"エンジュは、屋根のはしで止まった。動かない。しっぽの火が、小さい。"},{w:"hero",f:"surprised",t:"……エンジュ？"},{w:null,t:"空の火の鳥は、回り続けているだけだった。"}];
CN_SC.c13_2l=[{w:null,t:"黒い角の子の一撃で、エンジュが屋根の上をころがった。"},{w:null,t:"黒い角の子が、まっすぐセイリュの方へ走った。"},{w:"hero",f:"angry",t:"エンジュ！"},{w:null,t:"エンジュが、セイリュとエリーの前に飛びこんだ。"},{w:null,t:"角が、エンジュの体を、屋根のはしまではじき飛ばした。"},{w:null,t:"エンジュは、屋根のはしで止まった。動かない。しっぽの火が、小さい。"},{w:"hero",f:"surprised",t:"……エンジュ？"},{w:null,t:"空の火の鳥は、回り続けているだけだった。"}];
CN_SC.c13_3=[{w:"dimi",t:"……竜は、また今度だ。"},{w:"hero",f:"angry",t:"レン！"},{w:"dimi",t:"……三人もいて、それか。"},{w:null,t:"レンは、黒い角の子をつれて、となりの線路を走る列車へ飛び移った。"},{w:null,t:"火の鳥が、その上を追っていった。"},{w:null,t:"ヤマトは、屋根の上をはって、エンジュのそばまで行った。"},{w:null,t:"しっぽの火に、手のひらをかざした。まだ、あたたかかった。"},{w:null,t:"第13話　おわり"}];
CN_SC.c14_1=[{w:null,t:"第14話　止まった列車のそば"},{w:null,t:"夜明け。列車は、畑のまん中で止まっていた。前の方で、線路が切られていた。"},{w:null,t:"線路わきの草の上に、エンジュが寝かされていた。目をあけない。"},{w:"lifa",f:"serious",t:"息はしてる。骨も、たぶん大丈夫。……でも、起きない。"},{w:"hao",f:"normal",t:"水、くんでくる。"},{w:null,t:"ハオは、走っていった。"},{w:null,t:"ヤマトは、エンジュの横にすわって、しっぽの小さな火を見ていた。"}];
CN_SC.c14_2=[{w:"hero",f:"sad",t:"……おれが、一人で屋根に上がったから。"},{w:"alek",f:"normal",t:"そうだな。"},{w:"elly",f:"surprised",t:"アレク！"},{w:"alek",f:"normal",t:"待てって言った。"},{w:null,t:"ヤマトは、何か言おうとして、口をあけた。声が出なかった。"},{w:null,t:"ひざの上に、ぽたっと水が落ちた。もう一つ。"},{w:"hero",f:"sad",t:"……おれだけじゃ、無理だ。"},{w:null,t:"ヤマトは、鼻をすすった。止まらなかった。"},{w:"alek",f:"normal",t:"……一人でやる気だったのか。おれら、何しに来たんだよ。"},{w:"hero",f:"sad",t:"……。"},{w:"alek",f:"normal",t:"次は、待てって言ったら待て。"},{w:"hero",f:"sad",t:"……うん。"}];
CN_SC.c14_3=[{w:null,t:"ヤマトは、そでで顔をふいた。顔を上げると、エリーの手が見えた。"},{w:null,t:"セイリュを抱えたエリーの手が、小さく、ずっとふるえていた。"},{w:"hero",f:"surprised",t:"……エリー、手。"},{w:"elly",f:"smile",t:"……寒いだけ。"},{w:"hero",f:"normal",t:"……夏だぞ。"},{w:"elly",f:"smile",t:"ギリシャより、寒いの。"},{w:null,t:"エリーは、セイリュを抱えなおした。ふるえは、止まらなかった。"},{w:null,t:"ヤマトは、それ以上、何も言わなかった。"}];
CN_SC.c14_4=[{w:null,t:"畑の向こうから、空を飛ぶ機械が三つ、近づいてきた。"},{w:"x",n:"ゼロデイの手下",t:"止まった列車だ。竜はこの辺にいるぞ！"},{w:"hao",f:"angry",t:"水くみに行ったら、これだ。"},{w:"hero",f:"serious",t:"……エンジュは、出せない。"},{w:"alek",f:"normal",t:"クロッコが前。ピリポンはうしろから雷。"},{w:"elly",f:"normal",t:"ヤマトは、コグリフ。"},{w:"hero",f:"normal",t:"……任せる。"}];
CN_DIR.c14_4={"k": "勝負", "t": "ゼロデイの手下・盤＝畑と線路（平原が多い）・覚えること＝仲間に任せる。エンジュは出せない。仲間の子（クロッコ・ピリポン）と、コグリフで戦う。一体で何でもやらず、前・うしろに役を分ける。"};
CN_SC.c14_5w=[{w:"x",n:"ゼロデイの手下",t:"くそっ、出直しだ！"},{w:"hao",f:"smile",t:"……水、こぼさずに戻ってこれた。"},{w:null,t:"静かになった。エンジュのしっぽの火が、少しだけ大きくなっていた。"}];
CN_SC.c14_5l=[{w:"x",n:"ゼロデイの手下",t:"竜はどこだ……。おい、この辺の畑、広すぎるぞ。"},{w:"x",n:"ゼロデイの手下",t:"ランサム様に聞け。"},{w:"x",n:"ゼロデイの手下",t:"ランサム様は、自分で探すって、向こうへ行った。"},{w:null,t:"手下たちは、竜を見つけられないまま、畑の向こうへ飛んでいった。"},{w:null,t:"静かになった。エンジュのしっぽの火が、少しだけ大きくなっていた。"}];
CN_SC.c14_6=[{w:null,t:"リーファが、荷物から、つぶれた包みを出した。中は、冷えた肉まん。"},{w:"lifa",f:"smile",t:"列車の売店の。……ちょっとつぶれてる。"},{w:null,t:"みんなが一つずつ取る。ヤマトは、手をのばさなかった。"},{w:null,t:"エリーが、だまって、自分の肉まんを半分にちぎった。"},{w:null,t:"半分を、ヤマトの前に差し出した。"},{w:null,t:"第14話　おわり"}];
CN_SC.c15_1=[{w:null,t:"第15話　凍った大河"},{w:null,t:"朝。線路わきの草の上で、エンジュが、片目をあけた。"},{w:"partner",t:"……うるさい。寝てたのに。"},{w:null,t:"ヤマトは、すぐに顔をそむけて、そでで目をこすった。"},{w:"elly",f:"smile",t:"エンジュ！"},{w:"partner",t:"……なんで、みんな見てる。"},{w:"alek",f:"normal",t:"見てない。"},{w:"lifa",f:"smile",t:"熱も、下がってる。歩ける？"},{w:"partner",t:"歩ける。……抱えるな。"},{w:"hero",f:"normal",t:"抱えてない。"}];
CN_SC.c15_2=[{w:null,t:"五人で北へ歩いた。昼すぎ、谷の向こうに、白く光る大きな川が見えた。"},{w:"hero",f:"surprised",t:"……凍ってる？　夏なのに。"},{w:"lifa",f:"normal",t:"……記録では、ここだけ、夏でも凍るの。わけは、分かってない。"},{w:"hao",f:"normal",t:"向こう岸へ渡る橋は、ずっと下だ。三日かかる。"},{w:"alek",f:"normal",t:"氷の上を歩けば、半日だ。"},{w:"elly",f:"sad",t:"……割れない？"},{w:"alek",f:"normal",t:"たぶん。"},{w:"elly",f:"angry",t:"たぶんって何！"},{w:null,t:"五人は、一列になって、氷の上を歩きだした。"}];
CN_SC.c15_3=[{w:null,t:"川のまん中あたりで、遠くから、ごりごりと低い音が近づいてきた。"},{w:"partner",t:"……下から、何か来る。"},{w:null,t:"氷を割りながら、黒い船がまっすぐ進んでくる。船首に、ゼロデイの印。"},{w:"x",n:"ゼロデイの手下",t:"いたいた！　氷の上なら、逃げ場はないぞ！"},{w:"hao",f:"angry",t:"船で追ってくるなよ……。"},{w:"elly",f:"normal",t:"雪と氷の上だよ。コグリフは、ここだと強い。"},{w:"alek",f:"normal",t:"向こうは水の子だ。氷の上なら、水の得はない。"}];
CN_DIR.c15_3={"k": "勝負", "t": "ゼロデイの手下（砕氷船から下りてきた子たち）・盤＝凍った大河（雪原と氷が多い）・覚えること＝氷の上の盤。雪の上では、氷の子と光の子が強い。水の子は、水がないと得がない。光のコグリフを前に出す。"};
CN_SC.c15_4w=[{w:"x",n:"ゼロデイの手下",t:"くそっ、船ごと行け！　氷ごと割ってやれ！"},{w:"hao",f:"surprised",t:"本気か、あいつら。"},{w:null,t:"砕氷船が、全速で突っこんできた。氷に、長いひびが走る。"},{w:"hero",f:"serious",t:"走れ！"},{w:null,t:"五人の足もとで、氷が、大きく割れた。"},{w:null,t:"第15話　おわり"}];
CN_SC.c15_4l=[{w:"x",n:"ゼロデイの手下",t:"はい、氷の上でつかまえた。"},{w:null,t:"手下が手をのばした時、足もとの氷が、ぴしりと鳴った。"},{w:null,t:"砕氷船が、全速で突っこんできた。氷に、長いひびが走る。"},{w:"hero",f:"serious",t:"走れ！"},{w:null,t:"五人の足もとで、氷が、大きく割れた。"},{w:null,t:"第15話　おわり"}];
CN_SC.c16_1=[{w:null,t:"第16話　氷の下の玄武"},{w:null,t:"割れた氷のすき間から、冷たい水があふれた。五人の足が、すべる。"},{w:"elly",f:"surprised",t:"ハオ、呼ぶ所！"},{w:null,t:"ハオが、古い発音で唱えた。エリーが「ほー、ほー」と重ねた。"},{w:null,t:"割れ目の下の暗い水の中で、何かが、ゆっくり動いた。"},{w:null,t:"その時、氷の下から、大きな黒い岩が持ち上がった。"},{w:null,t:"岩ではなかった。こうらだった。五人は、そのこうらの上に乗っていた。"},{w:"hao",f:"surprised",t:"……亀？"},{w:"lifa",f:"surprised",t:"玄武……！"},{w:null,t:"こうらから、長い首がのびた。首に、白い霜がついている。"},{w:null,t:"大きな亀の頭は、五人の顔を見なかった。セイリュの前で止まった。"},{w:null,t:"亀は、鼻先で、セイリュの角に、そっとふれた。"},{w:null,t:"それから、古い言葉を一言だけ言った。"},{w:"hao",f:"normal",t:"……「乗れ」。……セイリュに言ってる。"},{w:"hao",f:"angry",t:"……おれたちは、ついでか。"},{w:"partner",t:"ついでだな。"}];
CN_SC.c16_2=[{w:null,t:"亀は、氷を割りながら、ゆっくり向こう岸へ泳ぎだした。"},{w:null,t:"水の中に、小さな亀の子たちが、ころころと浮かんでいた。生まれたばかりだ。"},{w:null,t:"大きな亀は、その子たちの所だけ、大きく回ってよけた。"},{w:"elly",f:"surprised",t:"……よけた。"},{w:"alek",f:"normal",t:"淵の主と、同じだな。"},{w:"hero",f:"normal",t:"……古い子って、みんなそうなのか。"},{w:null,t:"うしろから、砕氷船のエンジンの音が追ってきた。"},{w:"x",n:"ゼロデイの手下",t:"亀ごとつかまえろ！　ランサム様が喜ぶぞ！"},{w:"alek",f:"serious",t:"亀の上で守るぞ。亀に乗られたら、終わりだ。"}];
CN_DIR.c16_2={"k": "勝負", "t": "ゼロデイの手下（砕氷船から）・盤＝玄武のこうらの上と水（水辺と氷）・覚えること＝古代を運び、守る。玄武は戦わずに泳ぎ続ける。玄武とセイリュのいるマスに、相手を近づけない。"};
CN_SC.c16_3w=[{w:"x",n:"ゼロデイの手下",t:"近づけねえ……。船、止めろ！"},{w:"partner",t:"水の上は、きらいだ。"},{w:null,t:"砕氷船は、氷の厚い所につかえて、止まった。"}];
CN_SC.c16_3l=[{w:null,t:"手下の子が一体、こうらに飛び移った。"},{w:null,t:"亀が、こうらを一回だけゆすった。手下の子は、水の中へ落ちていった。"},{w:"x",n:"ゼロデイの手下",t:"……あれ、反則だろ。"},{w:null,t:"砕氷船は、氷の厚い所につかえて、止まった。"}];
CN_SC.c16_4=[{w:null,t:"向こう岸に着くと、亀は、五人をこうらから下ろした。"},{w:null,t:"こうらの模様の中に、古い字が、一行だけあった。"},{w:"lifa",f:"normal",t:"……読むわね。"},{w:null,t:"端末が読み上げた。「北の一句　亀は、水の底で目をあける」"},{w:"hao",f:"normal",t:"北のかけら、これだ。"},{w:null,t:"亀は、セイリュをもう一度だけ見て、氷の下へ沈んでいった。"}];
CN_SC.c16_5=[{w:null,t:"夜。岸の岩かげで、たき火をした。"},{w:null,t:"セイリュは、ヤマトのひざの上で、丸くなって眠っていた。地面には、おりていない。"},{w:"partner",t:"……寝相、よくなったな。"},{w:"hero",f:"normal",t:"……ほんとだ。"},{w:"lifa",f:"normal",t:"熱も、少し下がってる。"}];
CN_SC.c16_6=[{w:null,t:"夜明け。川霧が晴れると、対岸の丘の上に、長い灰色の壁が見えた。"},{w:"hao",f:"surprised",t:"……古い都の城壁だ。"},{w:"alek",f:"normal",t:"思ったより、近いな。"},{w:null,t:"第16話　おわり"}];
CN_SC.c17_1=[{w:null,t:"第17話　古い都の門"},{w:null,t:"朝。五人で、灰色の城壁の下まで歩いた。南の門は、閉じている。"},{w:null,t:"門の前の霧の中を、金色の角の子が、ふわりと横切った。"},{w:"hero",f:"surprised",t:"……今の、何？　鹿？"},{w:"hao",f:"surprised",t:"麒麟だ。いいことの前に出るって、師匠が言ってた。"},{w:"partner",t:"……もう、いない。"},{w:"lifa",f:"normal",t:"写真、撮れなかった……。"},{w:"alek",f:"normal",t:"またか。"}];
CN_SC.c17_3=[{w:null,t:"南の門の両わきに、石の獅子の像が二体。動かない、ただの飾りだった。"},{w:null,t:"門をくぐると、碁盤の目の通り。古い屋根の家が、どこまでも並んでいた。"},{w:null,t:"鐘楼の広場のすみに、古い書庫の建物があった。戸の前に、老人が一人。"},{w:"x",n:"老人",t:"……若い客は、めずらしい。"},{w:null,t:"老人は、ヤマトのポケットからのぞいているルーペに目をとめた。"},{w:"x",n:"老人",t:"そのルーペ。……ゲンイチのか。"},{w:"hero",f:"surprised",t:"じいちゃんの！　知り合い？"},{w:"x",n:"老人",t:"昔、いっしょに土を掘った。……あいつは、元気か。"},{w:"hero",f:"normal",t:"この前、電話、いきなり切られた。"},{w:"x",n:"老人",t:"……変わらんな。"},{w:"x",n:"老人",t:"旅の話を、何か集めてきたか。"},{w:"elly",f:"normal",t:"西は、「虎は、朝の来る方へ吠える」。"},{w:"alek",f:"normal",t:"南は、「鳥は、海の上で輪を描く」。"},{w:"hao",f:"normal",t:"北は、「亀は、水の底で目をあける」。"},{w:"x",n:"老人",t:"……東が、足りんな。"}];
CN_SC.c17_4=[{w:"lifa",f:"serious",t:"ここ、昔の記録が残ってるんですか。三年前のも。"},{w:"x",n:"老人",t:"紙の記録だけはな。機械の記録は、すぐ消されるが。"},{w:"lifa",f:"surprised",t:"……消される。"},{w:"x",n:"老人",t:"見たいなら、あしたの朝、開ける。今日は、もう鍵を閉めた。"},{w:"hero",f:"normal",t:"今、開けてよ。"},{w:"x",n:"老人",t:"鍵は、ゲンイチと同じで、気まぐれでな。"},{w:null,t:"書庫の奥の、重い扉。その向こうに、記録の棚が、暗く並んでいた。"},{w:null,t:"第17話　おわり"}];
CN_SC.c18_1=[{w:null,t:"第18話　記録庫"},{w:null,t:"朝。老人が、重い扉の鍵を、三回まちがえてから開けた。"},{w:"x",n:"老人",t:"……ほらな。気まぐれだ。"},{w:null,t:"中は、紙のにおい。天井まで、記録の箱が積まれている。"},{w:"lifa",f:"serious",t:"三年前の、大停電の箱は……。"},{w:"x",n:"老人",t:"奥から三番目の棚。上から二段目。"},{w:"hao",f:"surprised",t:"覚えてるのかよ。"},{w:"x",n:"老人",t:"ほかに、することがないからな。"}];
CN_SC.c18_2a=[{w:null,t:"箱の中は、紙の報告書の束。字が、細かい。"},{w:"alek",f:"normal",t:"ヤマト。ルーペ。"},{w:"hero",f:"normal",t:"あ、うん。"}];
CN_SC.c18_2b=[{w:null,t:"ルーペの下に、一枚の紙。「停電の責任者」の欄に、名前が一つあった。"},{w:"hero",f:"surprised",t:"……この名字。"},{w:"elly",f:"surprised",t:"レンと、同じ。"},{w:"alek",f:"serious",t:"うわさのとおりだ。"},{w:"lifa",f:"normal",t:"下にも、何か書いてある。……最後の操作の記録。"},{w:null,t:"「最後に端末を開いた日　三年前の四月九日」"},{w:"hao",f:"normal",t:"停電の、何日前だ。"},{w:"lifa",f:"normal",t:"……ちょうど、ひと月前。"},{w:"hero",f:"normal",t:"ひと月、何してたんだろ。"},{w:"x",n:"老人",t:"……記録には、ない。"}];
CN_DIR.c18_2={"k": "調べる", "t": "記録の箱・ルーペで、紙の報告書を調べる・覚えること＝調べる。名前と日付のある紙を見つける。関係のない紙もまじっている。"};
CN_SC.c18_3=[{w:"x",n:"老人",t:"その名前の男は、停電のあと、技師をやめさせられた。"},{w:"elly",f:"surprised",t:"……それから？"},{w:"x",n:"老人",t:"……記録には、ない。"},{w:null,t:"老人は、箱のふたを、ゆっくり閉めた。"},{w:"x",n:"老人",t:"ゲンイチに言っとけ。こんな箱ばかり、たまってると。"},{w:"hero",f:"normal",t:"……電話、出ないかもしれないけど。"}];
CN_SC.c18_4=[{w:null,t:"記録庫の窓の外。壁にもたれて、レンが立っていた。"},{w:null,t:"レンは、ポケットから端末を出した。画面の写真を開く。"},{w:null,t:"男の人と、小さいころのレン。盤をはさんで、笑っている。"},{w:null,t:"写真のすみに、小さな字で日付があった。「四月九日」"},{w:null,t:"レンは、端末を閉じた。火の鳥が、屋根の上で、羽をたたんでいた。"},{w:null,t:"第18話　おわり"}];
CN_SC.c19_1=[{w:null,t:"第19話　停電の夜の日誌"},{w:null,t:"朝。記録庫の老人が、もう一つ、ほこりだらけの箱を出してきた。"},{w:"x",n:"老人",t:"停電の夜の、当番日誌だ。だれも読みに来なかった。"},{w:"lifa",f:"serious",t:"……読みます。"},{w:null,t:"手書きの字。最後のページだけ、字が乱れていた。"},{w:"lifa",f:"serious",t:"「外から命令。止まらない。主任が、手で止めようとしている」"},{w:"elly",f:"surprised",t:"主任って……。"},{w:"alek",f:"normal",t:"レンの父親だ。日付も、停電の夜だ。"},{w:"lifa",f:"serious",t:"命令の出どころに、印がある。……第七棟と、同じ。ゼロデイ。"},{w:"hao",f:"angry",t:"ゼロデイが、停電を起こしたのか。"},{w:"alek",f:"normal",t:"街を一つ、止められるか。試したんだ。"},{w:"lifa",f:"sad",t:"……止めようとした人が、責任者にされたの？"}];
CN_SC.c19_2=[{w:null,t:"日誌の下に、もう一枚。「責任者を決める書類」。下に、署名が一つ。"},{w:"hero",f:"normal",t:"……アドリアン。"},{w:"hao",f:"normal",t:"だれだ、それ。"},{w:"lifa",f:"normal",t:"知らない名前。都の役所の人じゃない。"},{w:"x",n:"老人",t:"……その名前は、どこにも、ほかに出てこん。"},{w:"hero",f:"normal",t:"じいちゃんに、聞いてみる。"},{w:"elly",f:"surprised",t:"電話、出る？"},{w:"hero",f:"normal",t:"……出なかったら、かけ続ける。"}];
CN_SC.c19_3=[{w:null,t:"三回目で、じいちゃんが出た。画面の後ろで、ハナがパンをかじっている。"},{w:"genichi",t:"……なんだ。朝めしの途中だぞ。",ph:1},{w:"hero",f:"normal",t:"じいちゃん。アドリアンって名前、聞いたこと、ある？"},{w:null,t:"じいちゃんの顔が、動かなくなった。"},{w:"hero",f:"surprised",t:"……じいちゃん？"},{w:null,t:"しばらく、だれも、何も言わなかった。"},{w:"genichi",t:"……どこで、その名前を。",ph:1},{w:"hero",f:"normal",t:"古い都の、記録庫。"},{w:"genichi",t:"……危ない所には、行くなと言われとるだろう。",ph:1},{w:null,t:"画面は、そこで切れた。"},{w:"partner",t:"……また切った。"}];
CN_SC.c19_4=[{w:null,t:"記録庫の外が、さわがしくなった。ゼロデイの手下と、レン。"},{w:"x",n:"ゼロデイの手下",t:"その箱、全部燃やせって命令だ！"},{w:null,t:"レンの横に、黒い角の子。首が、赤く光っている。"},{w:"dimi",t:"……どけ。"},{w:"hero",f:"angry",t:"どかない。この箱、おまえの——"},{w:"alek",f:"serious",t:"今は、勝負だ。"}];
CN_DIR.c19_4={"k": "勝負", "t": "レン（黒い角の子）とゼロデイの手下・盤＝古い都の石畳（遺跡）・覚えること＝ライバルの真相。黒い角の子は強いが、まわりの子を守らない。相手の手下の子から先に倒すと、黒い角の子は一体で残る。"};
CN_SC.c19_5w=[{w:null,t:"手下の子たちが、次々に石畳に倒れた。"},{w:"x",n:"ゼロデイの手下",t:"おい！　黒いの！　うちの子、起こすの手伝え！"},{w:null,t:"黒い角の子は、倒れた子の上を、またいで通った。ふり返らなかった。"},{w:"x",n:"ゼロデイの手下",t:"……おい。"},{w:null,t:"レンの足が、一度だけ止まった。"},{w:"x",n:"ゼロデイの手下",t:"……撤収だ。箱は、また今度。"},{w:null,t:"手下は、倒れた子を自分で抱えて、門の方へ走っていった。"}];
CN_SC.c19_5l=[{w:"x",n:"ゼロデイの手下",t:"よし、箱をよこせ！"},{w:null,t:"手下が手をのばした時、手下の子が一体、石畳に倒れたまま動けなくなっていた。"},{w:"x",n:"ゼロデイの手下",t:"おい！　黒いの！　うちの子、起こすの手伝え！"},{w:null,t:"黒い角の子は、倒れた子の上を、またいで通った。ふり返らなかった。"},{w:"x",n:"ゼロデイの手下",t:"……おい。"},{w:null,t:"レンの足が、一度だけ止まった。"},{w:"x",n:"ゼロデイの手下",t:"……撤収だ。箱は、また今度。"},{w:null,t:"手下は、倒れた子を自分で抱えて、門の方へ走っていった。"}];
CN_SC.c19_6=[{w:null,t:"ヤマトは、書類の紙を一枚持って、レンの前に立った。"},{w:"hero",f:"normal",t:"これ。"},{w:null,t:"レンは、紙を受け取った。署名の所で、目が止まった。"},{w:null,t:"レンは、紙を四つにたたんで、ポケットに入れた。"},{w:null,t:"ヤマトは、まだ、レンの顔を見ていた。"},{w:"dimi",t:"……こっち見んな。"},{w:null,t:"レンは、黒い角の子をつれて、門の外へ歩いていった。"},{w:null,t:"第19話　おわり"}];
CN_SC.c20_1=[{w:null,t:"第20話　都を守る"},{w:null,t:"昼。都の南門の外に、ゼロデイの車が二十台。空には、飛ぶ機械の群れ。"},{w:null,t:"まん中の車の上に、ランサムが立っていた。"},{w:"ransom",t:"記録庫を燃やせ。竜も取る。……全部、おれがやる。"},{w:"patch",t:"ランサム様、わたしたちも手伝い——"},{w:"ransom",t:"いらん。おまえらは見てろ。"},{w:"log",t:"見てるのは、得意だ。"},{w:null,t:"ランサムは、一人で、子を何体も出して、門へ向かってきた。"}];
CN_SC.c20_2=[{w:null,t:"都の通りに、鐘の音が鳴りひびいた。"},{w:"x",n:"都の衛兵",t:"門を閉めろ！　子どもたちは、中へ！"},{w:"hero",f:"serious",t:"おれたちも出る。"},{w:"x",n:"都の衛兵",t:"ばか言うな。"},{w:"x",n:"メイリン",t:"出してあげて。あの子たち、門の前で麒麟を見た子よ。"},{w:"hao",f:"surprised",t:"……メイリンさん。都でいちばん強い人だ。"},{w:"x",n:"メイリン",t:"衛兵は右。わたしは左。子どもたちは、まん中。"},{w:"alek",f:"normal",t:"まん中、いちばん大変な所だな。"},{w:"x",n:"メイリン",t:"でしょうね。"},{w:null,t:"セイリュが、アレクのクロッコの横に、すべりこんだ。"},{w:"alek",f:"normal",t:"……おまえ、乗る気か。"},{w:null,t:"二体が、水しぶきの中で重なった。長い、水の竜。"},{w:"lifa",f:"serious",t:"……セイリュ、熱が上がる。早く終わらせて。"}];
CN_DIR.c20_2={"k": "勝負", "t": "ランサム（何体も同時に出してくる）・盤＝古い都の通り（遺跡・石畳）・覚えること＝町の人と組む盤。衛兵とメイリンの子が、こちらの味方として盤に入る。一体ずつ相手をせず、味方と相手を分けあう。融合は、ヤマトのセイリュとアレクのクロッコ（クロベク）でリヴァイア（竜）。"};
CN_SC.c20_3w=[{w:"ransom",t:"……右も、左も、まん中も。……なんで全部、手が足りない。"},{w:"patch",t:"だから、手伝うって言ったのに！"},{w:null,t:"門の外で、ランサムの子たちが、ばらばらに下がりはじめた。"},{w:"ransom",t:"……撤収。……おれが決めた撤収だ。"},{w:null,t:"ランサムの車が、土ぼこりを上げて、西へ走りだした。"}];
CN_SC.c20_3l=[{w:"ransom",t:"ほらな。おれ一人で十分だ。"},{w:null,t:"その時、ランサムの左右の子が、衛兵とメイリンの子に押し返されて、下がった。"},{w:"ransom",t:"……おい、右！　左も！　……だれか！"},{w:"log",t:"さっき、いらんって。"},{w:null,t:"門の外で、ランサムの子たちが、ばらばらに下がりはじめた。"},{w:"ransom",t:"……撤収。……おれが決めた撤収だ。"},{w:null,t:"ランサムの車が、土ぼこりを上げて、西へ走りだした。"}];
CN_SC.c20_4=[{w:"hao",f:"angry",t:"逃げた！　どこ行く気だ。"},{w:"lifa",f:"serious",t:"研究所のAIで、追える。"},{w:"hao",f:"angry",t:"また機械か。"},{w:null,t:"リーファは、AIの出した道すじを、紙の地図に、自分の指でなぞった。"},{w:null,t:"道の幅。橋の場所。車の速さ。一つずつ、指で確かめていく。"},{w:"lifa",f:"normal",t:"……合ってる。じゃあ、使う。"},{w:"hao",f:"surprised",t:"……確かめてから、言ったな。"},{w:"lifa",f:"smile",t:"でしょ。"},{w:null,t:"端末の地図の上を、赤い点が、西へ動いていく。都をはなれ、砂の国の方へ。"},{w:"lifa",f:"serious",t:"港に着いた。……船に乗りかえてる。"},{w:"alek",f:"normal",t:"西の海か。ずいぶん遠くまで逃げるな。"},{w:null,t:"赤い点は、海の上に出て、ゆっくり西へ小さくなっていった。"},{w:null,t:"第20話　おわり"}];
CN_SC.c21_1=[{w:null,t:"第21話　雪の高原"},{w:null,t:"古い都の北門。五人は、雪をかぶった高い山の方を見上げた。"},{w:"alek",f:"normal",t:"東の海へ行く空の船は、あの高原の上から出る。"},{w:"hao",f:"surprised",t:"あの上？　山、まっ白だぞ。"},{w:"lifa",f:"serious",t:"……セイリュ、ゆうべから何も食べてない。"},{w:null,t:"セイリュは、ヤマトの上着の中で、目を半分だけあけていた。"},{w:"hero",f:"serious",t:"急ごう。"},{w:"partner",t:"寒い所は、きらいだ。"},{w:"hero",f:"normal",t:"知らん。行くぞ。"}];
CN_SC.c21_2=[{w:null,t:"登るにつれて、風が強くなった。足もとは、ひざまでの雪。"},{w:"elly",f:"sad",t:"……セイリュ、ふるえてる。"},{w:"lifa",f:"serious",t:"熱が上がってる。寒さで、体が追いつかないの。"},{w:null,t:"雪の向こうから、エンジンの音。ゼロデイの雪の車が二台。"},{w:"x",n:"ゼロデイの手下",t:"いたぞ！　竜は、もう弱ってるはずだ！"},{w:"hao",f:"angry",t:"どこまで来るんだよ……。"},{w:"alek",f:"normal",t:"雪の上だ。竜は、ここだと弱る。セイリュは出すな。"},{w:"elly",f:"normal",t:"コグリフは強いよ。雪でも、光る。"}];
CN_DIR.c21_2={"k": "勝負", "t": "ゼロデイの手下・盤＝雪原・覚えること＝雪原。雪の上では、氷の子と光の子が強く、竜は弱る（`TYPE_TERR` の竜：雪で下がる）。光のコグリフを前に。"};
CN_SC.c21_3w=[{w:"x",n:"ゼロデイの手下",t:"くそっ、寒い！　車に戻れ！"},{w:null,t:"手下が引いていく。雪の丘の上に、白い影がいくつも並んでいた。"},{w:null,t:"大きな雪の豹の群れだった。先頭の一頭は、ひときわ大きい。"},{w:"x",n:"ゼロデイの手下",t:"……あれ、野生の長だ。逃げろ！"},{w:null,t:"手下たちの車は、雪けむりを上げて、下へ走っていった。"}];
CN_SC.c21_3l=[{w:"x",n:"ゼロデイの手下",t:"はい、竜をよこせ。"},{w:null,t:"手下が近づいた時、雪の丘の上に、白い影がいくつも並んだ。"},{w:null,t:"大きな雪の豹の群れだった。先頭の一頭は、ひときわ大きい。"},{w:"x",n:"ゼロデイの手下",t:"……あれ、野生の長だ。逃げろ！"},{w:null,t:"手下たちの車は、雪けむりを上げて、下へ走っていった。"}];
CN_SC.c21_4=[{w:null,t:"大きな豹が、ゆっくり五人の前に下りてきた。"},{w:"hao",f:"surprised",t:"……ユキヒョウガだ。雪の高原の長。"},{w:"partner",t:"……こっち見てない。セイリュを見てる。"},{w:null,t:"長は、セイリュのにおいをかいだ。それから、くるりと背を向けた。"},{w:null,t:"少し歩いて、ふり返る。また少し歩いて、ふり返る。"},{w:"elly",f:"surprised",t:"……ついてこいって？"},{w:"alek",f:"normal",t:"たぶんな。"}];
CN_SC.c21_5=[{w:null,t:"連れていかれたのは、大きな岩の穴だった。中に、豹の子どもたちが丸まっている。"},{w:null,t:"豹の子たちは、セイリュのまわりに、ぎゅっと集まってきた。"},{w:"lifa",f:"surprised",t:"……ここ、外より五度は高い。"},{w:"hero",f:"normal",t:"……おまえら、湯たんぽか。"},{w:null,t:"いちばん小さな豹の子が、アレクの上着の中に、もぐりこんだ。ユキマダラだ。"},{w:"alek",f:"normal",t:"……出ろ。"},{w:"elly",f:"smile",t:"出ないって。"},{w:null,t:"穴の外で、風の音が強くなった。雪が、横に流れていく。"},{w:null,t:"その夜から、吹雪は、三日やまなかった。"},{w:null,t:"第21話　おわり"}];
CN_SC.c22_1=[{w:null,t:"第22話　吹雪の穴"},{w:null,t:"吹雪の三日目。岩の穴の中は、豹の子たちの寝息と、風の音だけ。"},{w:"hao",f:"angry",t:"……三日だぞ。干し肉、あと二枚。"},{w:"alek",f:"normal",t:"一枚ずつ半分だ。"},{w:"elly",f:"normal",t:"豹の子にも、あげていい？"},{w:"hao",f:"angry",t:"……半分の半分かよ。"},{w:null,t:"セイリュは、豹の子にはさまれて、じっと目を閉じていた。"}];
CN_SC.c22_2=[{w:"hero",f:"normal",t:"薪、取ってくる。穴の外に、枯れ木があった。"},{w:"lifa",f:"serious",t:"すぐ戻ってね。"},{w:null,t:"ヤマトが立ち上がって、穴の入口へ向かった。"},{w:null,t:"うしろで、ずる、と音がした。"},{w:null,t:"セイリュが、豹の子の間からはい出て、ヤマトの方へ、体を引きずってきた。"},{w:"elly",f:"surprised",t:"セイリュ、動いちゃだめ！"},{w:null,t:"ヤマトは、入口で止まった。ふり返って、しばらくセイリュを見ていた。"},{w:null,t:"セイリュの首のチップが、外の風の音に合わせるように、かすかに光っていた。"},{w:"hero",f:"normal",t:"……こいつ、おれが出ると、ついてくる。"},{w:"partner",t:"昨日も、そうだった。"},{w:"hero",f:"surprised",t:"……言えよ。"},{w:"partner",t:"見てると思った。"},{w:null,t:"ヤマトは、上着をぬいで、セイリュにかけた。それから、その横に座った。"},{w:"hero",f:"normal",t:"……薪、あとでいいや。"},{w:"alek",f:"normal",t:"じゃあ、おれが行く。"},{w:null,t:"アレクが、だまって外へ出ていった。"}];
CN_SC.c22_3=[{w:null,t:"夕方。吹雪が、急に弱まった。雲のすき間から、うすい日がさした。"},{w:"alek",f:"serious",t:"今のうちに、船乗り場まで行く。次の吹雪が来る前に。"},{w:"lifa",f:"serious",t:"セイリュ、歩けない。抱えていくしかない。"},{w:null,t:"穴を出ると、雪の上に、ゼロデイの手下が三人待っていた。"},{w:"x",n:"ゼロデイの手下",t:"三日、待ったぞ。寒かったぞ！"},{w:"hao",f:"normal",t:"……そっちも、外で待ってたのか。"},{w:"x",n:"ゼロデイの手下",t:"車の中だ！　でも寒かった！"},{w:"hero",f:"serious",t:"セイリュは、おれが抱えてる。エンジュ、前。"}];
CN_DIR.c22_3={"k": "勝負", "t": "ゼロデイの手下・盤＝雪原の短い道・覚えること＝弱った子と旅する。セイリュは盤の上にいるが、戦えない。セイリュのいるマスに相手を近づけないまま、道の先の出口まで進む。豹の長が一体、味方に入る【案】。"};
CN_SC.c22_4w=[{w:"x",n:"ゼロデイの手下",t:"三日待って、これかよ！"},{w:"hao",f:"smile",t:"車の中で、待ってりゃよかったのに。"},{w:null,t:"手下たちは、雪の車に飛び乗って、山の下へ逃げていった。"}];
CN_SC.c22_4l=[{w:"x",n:"ゼロデイの手下",t:"はい、竜は——"},{w:null,t:"豹の長が、手下の前にどすんと下りた。手下は、雪の中にしりもちをついた。"},{w:"x",n:"ゼロデイの手下",t:"……だから野生の長は、いやなんだ。"},{w:null,t:"手下たちは、雪の車に飛び乗って、山の下へ逃げていった。"}];
CN_SC.c22_5=[{w:null,t:"船乗り場の手前の、尾根の上。風が、ぴたりと止んだ。"},{w:null,t:"エンジュが、雪の上に耳をつけた。"},{w:"partner",t:"……東から。低い音。"},{w:"elly",f:"surprised",t:"低い音？"},{w:"partner",t:"ずっと遠く。海の方。"},{w:null,t:"ヤマトの腕の中で、セイリュが、ゆっくり首を持ち上げた。"},{w:null,t:"セイリュは、東の空の方を、じっと見ていた。"},{w:null,t:"第22話　おわり"}];
CN_SC.c23_1=[{w:null,t:"第23話　東の海辺"},{w:null,t:"空の船は、東の海辺の、小さな漁師町に下りた。潮のにおい。"},{w:null,t:"セイリュが、ヤマトの腕の中で、鼻をひくひくさせた。目が、少しあいた。"},{w:"elly",f:"smile",t:"セイリュ、起きた！"},{w:"lifa",f:"surprised",t:"……熱、少し下がってる。海の空気のせい？"},{w:"hao",f:"normal",t:"竜は、水の生き物だって、師匠が言ってた。"},{w:"partner",t:"……しょっぱいにおいがする。"},{w:"hao",f:"normal",t:"海だからな。"}];
CN_SC.c23_2=[{w:null,t:"船着き場には、漁船が並んでいた。でも、だれも乗っていない。"},{w:"x",n:"漁師",t:"今日は、どの船も出ないよ。島の方へは、とくにな。"},{w:"alek",f:"normal",t:"どうして。"},{w:"x",n:"漁師",t:"変な作業服の連中が、船着き場を見張ってる。"},{w:null,t:"桟橋の先に、ゼロデイの手下が二人。網の筒を肩にかけている。"},{w:"x",n:"ゼロデイの手下",t:"はい、ここから先は、通行止め。"},{w:"hao",f:"angry",t:"また、おまえらか。"},{w:"x",n:"ゼロデイの手下",t:"また、おれたちだ。"},{w:"lifa",f:"normal",t:"海の上は、雷がよく通るの。ビリトラ、行って。"},{w:"alek",f:"normal",t:"エンジュは、海に入ると弱る。岸の上からだ。"}];
CN_DIR.c23_2={"k": "勝負", "t": "ゼロデイの手下・盤＝海辺（海と岸）・覚えること＝海辺。水の子は海で射程が伸びる。炎は水・海で弱る。雷は海で強い。リーファのビリトラを前に。"};
CN_SC.c23_3w=[{w:"x",n:"ゼロデイの手下",t:"くそっ、通行止め、解除……。"},{w:null,t:"手下たちがしりもちをついた時、桟橋の向こうから、足音が近づいてきた。"},{w:null,t:"防波堤の上を、レンが一人で歩いてきた。頭の上を、火の鳥が回っている。"}];
CN_SC.c23_3l=[{w:"x",n:"ゼロデイの手下",t:"はい、通行止めは続行。"},{w:null,t:"手下が胸をはった時、桟橋の向こうから、足音が近づいてきた。"},{w:null,t:"防波堤の上を、レンが一人で歩いてきた。頭の上を、火の鳥が回っている。"}];
CN_SC.c23_4=[{w:"hero",f:"serious",t:"……レン。"},{w:null,t:"エンジュが、前に出た。レンは、立ち止まった。"},{w:"dimi",t:"……今日は、やらない。"},{w:"hao",f:"surprised",t:"……え？"},{w:null,t:"レンの足もとには、黒い角の子もいた。でも、レンは前に出さなかった。"},{w:"x",n:"ゼロデイの手下",t:"レン、手伝えよ！　そいつら——"},{w:"dimi",t:"うるさい。"},{w:null,t:"レンは、沖の方を見た。小さな島が一つ、かすんで見える。"},{w:"dimi",t:"……島に、ゼロデイが行った。"},{w:"hero",f:"surprised",t:"え？"},{w:null,t:"レンは、それだけ言って、防波堤の向こうへ歩いていった。"},{w:"elly",f:"surprised",t:"……今の、教えてくれたの？"},{w:"alek",f:"normal",t:"さあな。"},{w:null,t:"沖の島の上に、黒い煙が、細く上がっていた。"},{w:null,t:"第23話　おわり"}];
CN_SC.c24_1=[{w:null,t:"第24話　東の島の祠"},{w:null,t:"朝。漁師の小さな船で、五人は沖の島へわたった。人の家は、一つもない。"},{w:"x",n:"漁師",t:"帰りは、夕方に迎えに来る。煙が見えたら、来ないからな。"},{w:"hao",f:"angry",t:"来いよ。"},{w:null,t:"島の森に入ると、木の上から、いくつもの目がこっちを見ていた。"}];
CN_SC.c24_2=[{w:null,t:"ちょうちんみたいなお化けの子、ボロウル。木から木へ飛ぶ、ソヨモモ。"},{w:"elly",f:"surprised",t:"……この子たち、見たことある。日本の昔話の本で。"},{w:"lifa",f:"normal",t:"日本の言い伝えの子よ。中国の研究所で生まれたの。"},{w:"hero",f:"surprised",t:"なんで、中国で？"},{w:"lifa",f:"normal",t:"日本では、作れないから。"},{w:null,t:"ヤマトは、少しだけ黙った。"},{w:null,t:"枝のかげから、光る小さな虫の子が、ふわふわ飛び立った。ホタルンの群れ。"},{w:null,t:"群れは、ヤマトの頭のまわりを、ぐるぐる回った。"},{w:"partner",t:"……うるさい。"},{w:null,t:"ホタルンたちは、森の奥へ飛んで、枝のまわりで光って、止まった。"},{w:"alek",f:"normal",t:"ついてこい、って顔だな。"}];
CN_SC.c24_3=[{w:null,t:"森の奥に、古い木の鳥居と、小さな祠があった。苔だらけだ。"},{w:null,t:"鳥居のはしに、色のあせた木の札。"},{w:"hero",f:"surprised",t:"……日本の字だ。"},{w:"hao",f:"surprised",t:"読めるのか。"},{w:"hero",f:"normal",t:"「この島の子らを祀る」。……日本の人が建てたんだ。"},{w:null,t:"祠のまわりに、日本の言い伝えの子たちが、静かに集まっていた。"},{w:"hero",f:"normal",t:"……日本には、一体もいないのに。"},{w:null,t:"ホタルンたちが、祠の軒下に、小さな明かりのように並んだ。"},{w:"elly",f:"smile",t:"ここが、家なんだ。"},{w:null,t:"木の上から、ソヨモモが一体、すべるように飛んできて、エリーの肩にとまった。"},{w:"elly",f:"surprised",t:"……ピリポンが、にらんでる。"},{w:"x",n:"ピリポン",t:"ピリッ。"},{w:null,t:"コグリフが、軒下の光を、じっと見上げていた。光る物が好きなのだ。"}];
CN_SC.c24_4=[{w:null,t:"祠のうらの方から、がつん、がつんと土を掘る音がした。"},{w:null,t:"のぞくと、作業服の男たちが、機械で地面に大きな穴をあけていた。"},{w:"x",n:"ゼロデイの手下",t:"ガキだ！　掘るのを止めるな、見張りが相手しろ！"},{w:"hao",f:"angry",t:"祠のうしろを掘るなよ……。"},{w:null,t:"軒下のホタルンたちが、いっせいに飛び立って、森の右の方で輪になった。"},{w:"alek",f:"normal",t:"……見張りは、右から来るのか。"}];
CN_DIR.c24_4={"k": "勝負", "t": "ゼロデイの見張り・盤＝島の森（森が多い）・覚えること＝日本の言い伝えの子。ホタルンの群れが、見張りの来る方を教えてくれる（加勢ではなく道案内）。森では、森の子がよけやすく、炎は燃え広がる。森を焼かずに戦える所を探す。"};
CN_SC.c24_5w=[{w:"x",n:"ゼロデイの手下",t:"見張りが負けた！　掘る方、急げ！"},{w:null,t:"穴の底から、機械の男が叫んだ。「当たった！　岩の下に、何かいる！」"},{w:null,t:"穴の底の土が、ずしん、と一度ゆれた。"},{w:"partner",t:"……下で、でかいのが、寝てる。……八つ、息をしてる。"},{w:null,t:"第24話　おわり"}];
CN_SC.c24_5l=[{w:"x",n:"ゼロデイの手下",t:"はい、見張り成功。……掘る方、まだか？"},{w:null,t:"穴の底から、機械の男が叫んだ。「当たった！　岩の下に、何かいる！」"},{w:null,t:"穴の底の土が、ずしん、と一度ゆれた。"},{w:"partner",t:"……下で、でかいのが、寝てる。……八つ、息をしてる。"},{w:null,t:"第24話　おわり"}];
CN_SC.c25_1=[{w:null,t:"第25話　八つ首"},{w:null,t:"穴の底に、黒い岩のようなものが見えた。うろこだ。それが、八本、並んでいる。"},{w:"elly",f:"surprised",t:"……首？　これ、全部？"},{w:null,t:"穴のふちに、見覚えのある二人がいた。"},{w:"patch",t:"はい、そこまで！　ゼロデイのエリート、パッチ、島にも参上！"},{w:"log",t:"掘ったのは、おれ。"},{w:"patch",t:"言わなくていい！"},{w:null,t:"穴の底で、手下たちが、大きな金属の輪を、首の一本に運んでいた。"},{w:"alek",f:"serious",t:"……首輪か。古い子にはチップがないから、外からはめる気だ。"},{w:"hero",f:"angry",t:"やめろ！"},{w:"patch",t:"やめない！　これ、ランサム様の置いていった命令なんだから！"},{w:"log",t:"ランサム様、もう西の海の上だけどな。"},{w:"hao",f:"normal",t:"置いていった命令を、まだやってるのか。"},{w:"partner",t:"止める。"}];
CN_DIR.c25_1={"k": "勝負", "t": "ログ＆パッチ・盤＝島の森の穴のまわり（森と荒地）・覚えること＝ボスの前ぶれ。森では炎が燃え広がる。荒地では地の子が硬い。エンジュは森の側から撃つ。"};
CN_SC.c25_2w=[{w:"patch",t:"負けた！　……でも、もうはめちゃった！"},{w:null,t:"穴の底で、がちゃん、と重い音がした。"},{w:null,t:"首輪の上の小さな光が、赤くともった。"}];
CN_SC.c25_2l=[{w:"patch",t:"はい、エリートの勝ち！　はめちゃって！"},{w:null,t:"穴の底で、がちゃん、と重い音がした。"},{w:null,t:"首輪の上の小さな光が、赤くともった。"}];
CN_SC.c25_3=[{w:null,t:"地面が、大きくゆれた。穴のまわりの土が、くずれ落ちる。"},{w:null,t:"八本の首が、ゆっくり持ち上がった。目が、一つずつ開いていく。"},{w:"hao",f:"surprised",t:"……サジンオロチ。八つ首の竜……。"},{w:"lifa",f:"surprised",t:"竜……、本物の……。"},{w:"patch",t:"はい、命令！　ゼロデイの言うことを聞きなさい！"},{w:null,t:"首の一本が、パッチの方を向いた。ほかの七本は、ばらばらの方を向いていた。"},{w:"log",t:"……八本とも、聞いてないぞ。"},{w:"patch",t:"一本は聞いてる！"},{w:null,t:"その一本が、大きく口を開けた。パッチとログは、穴のふちから転がり落ちた。"},{w:"patch",t:"聞いてないーっ！"},{w:"log",t:"上の作戦が、雑なんだって。"},{w:"patch",t:"今日は、ほんとに雑！"}];
CN_SC.c25_4=[{w:null,t:"八本の首が、てんでにほえた。空が鳴って、雷が森に落ちた。"},{w:null,t:"木に火がつく。ボロウルや、ソヨモモが、森の奥から逃げてくる。"},{w:"elly",f:"surprised",t:"島の子たちが！"},{w:null,t:"ホタルンの群れが飛び立った。逃げる子たちの前を飛んで、浜へ導いていく。"},{w:"hero",f:"serious",t:"……そっちは、たのむ。"},{w:"alek",f:"serious",t:"おれたちも下がるぞ。今のままじゃ、近づけない。"},{w:null,t:"ふり返ると、島の森が、赤くゆれていた。"},{w:null,t:"第25話　おわり"}];
CN_SC.c26_1=[{w:null,t:"第26話　首の輪"},{w:null,t:"燃える森の中で、八本の首が、てんでに砂の嵐を吐いていた。"},{w:"lifa",f:"serious",t:"あの首輪、まだ赤い。命令が、ぐちゃぐちゃに入ってる。"},{w:"hao",f:"angry",t:"ゼロデイの連中は？"},{w:"alek",f:"normal",t:"船で逃げた。パッチとログも。"},{w:"elly",f:"sad",t:"置いていったの？　あの子を？"},{w:null,t:"首の一本が、こっちを向いた。大きな口が開く。"},{w:"partner",t:"来るぞ。"}];
CN_SC.c26_2=[{w:null,t:"その時、カブトムシの子が飛びこんで、岩のかたまりを角ではじいた。"},{w:null,t:"煙の中から、レンが歩いてきた。頭の上を、火の鳥が回っている。"},{w:"hero",f:"surprised",t:"……レン。"},{w:"dimi",t:"……右の四本。"},{w:"hero",f:"normal",t:"じゃあ、左。"},{w:null,t:"二人は、それ以上、何も言わなかった。"},{w:"hao",f:"surprised",t:"……今の、相談だったのか？"},{w:"alek",f:"normal",t:"たぶんな。"},{w:"lifa",f:"serious",t:"首輪を、壊せたら止まる。でも、首は傷つけないで。"},{w:"partner",t:"輪だけか。"}];
CN_DIR.c26_2={"k": "勝負", "t": "サジンオロチ（八つ首・首輪で暴れている）・盤＝燃える森（森と荒地）・覚えること＝大きなボス戦。レンのカブトムシの子（ヘラツノ）が、この勝負だけ味方に入る。首を全部倒しに行かず、首輪のついた首までの道を、二人の子で開ける。融合は、アレクのユキマダラとエリーのソヨモモでフブキヤク（氷・氷は竜に強い）。オロチは竜と地の子なので、荒地からはなして、森の側で戦う。"};
CN_SC.c26_3w=[{w:null,t:"七本の首が、つかれて地面にたれた。首輪の首だけが、まだほえていた。"},{w:"dimi",t:"……今だ。"},{w:null,t:"ユキマダラとソヨモモが、跳んで重なった。吹雪をまとった、白い角の子。"},{w:null,t:"吹雪が、ほかの首を、つぎつぎに白く固めた。"},{w:"elly",f:"surprised",t:"……さむっ。"},{w:"alek",f:"normal",t:"森の火も、消えたな。"},{w:null,t:"エンジュが、首輪の首にかけ上がった。体が、光に包まれる。"},{w:null,t:"エンレオの姿のエンジュが、首輪に前足をかけた。"},{w:"partner",t:"……燃やす。輪だけ。"},{w:null,t:"白い火が、首輪だけを走った。金属が、ばきん、と割れて落ちた。"}];
CN_SC.c26_3l=[{w:null,t:"エンジュが、地面にたたきつけられた。でも、すぐに起き上がった。"},{w:"hero",f:"serious",t:"エンジュ、首輪の首まで、あと少し！"},{w:null,t:"レンのカブトムシの子が、ほかの首をおさえた。道が、一本だけ開いた。"},{w:null,t:"ユキマダラとソヨモモが、跳んで重なった。吹雪をまとった、白い角の子。"},{w:null,t:"吹雪が、ほかの首を、つぎつぎに白く固めた。"},{w:"elly",f:"surprised",t:"……さむっ。"},{w:"alek",f:"normal",t:"森の火も、消えたな。"},{w:null,t:"エンジュが、首輪の首にかけ上がった。体が、光に包まれる。"},{w:null,t:"エンレオの姿のエンジュが、首輪に前足をかけた。"},{w:"partner",t:"……燃やす。輪だけ。"},{w:null,t:"白い火が、首輪だけを走った。金属が、ばきん、と割れて落ちた。"}];
CN_SC.c26_4=[{w:null,t:"八本の首が、いっせいに動きを止めた。赤い光は、もうない。"},{w:null,t:"首は、一本ずつ、ゆっくり地面に下りていった。目が、閉じていく。"},{w:null,t:"空から、ぽつりと雨が落ちてきた。それから、ざあっと降りだした。"},{w:"elly",f:"surprised",t:"……雨。"},{w:"hao",f:"normal",t:"森の火が、消えてく。"},{w:null,t:"浜の方から、ホタルンの群れが、島の子たちを連れて戻ってきた。"},{w:null,t:"エンジュは、いつもの小さな狐に戻って、ヤマトの足もとで座りこんだ。"},{w:"partner",t:"……ぬれた。"}];
CN_SC.c26_5=[{w:null,t:"レンは、カブトムシの子を呼びもどして、浜の方へ歩きだした。"},{w:"hero",f:"normal",t:"……おい。"},{w:null,t:"レンは、ふり返らなかった。火の鳥が、その上を回ってついていった。"},{w:"elly",f:"normal",t:"……行っちゃった。"},{w:"alek",f:"normal",t:"あいつらしいな。"},{w:"hero",f:"normal",t:"……あいつ、今日、黒い角の子、出さなかった。"},{w:null,t:"雨の中で、八つ首の竜は、静かな寝息を立てていた。"},{w:null,t:"第26話　おわり"}];
CN_SC.c27_1=[{w:null,t:"第27話　海の門"},{w:null,t:"夜明け前の浜。五人は、漁師の小さな船の横で、三つの一句を並べた。"},{w:"alek",f:"normal",t:"西。「虎は、朝の来る方へ吠える」。"},{w:"hero",f:"normal",t:"朝の来る方。東だ。……ハオ、前にそう言ったら怒ったよな。"},{w:"hao",f:"angry",t:"東のどこか、が大事なんだ。"},{w:"lifa",f:"normal",t:"南は、「鳥は、海の上で輪を描く」。"},{w:"hao",f:"normal",t:"鳥……。火の鳥のことか？　あれ、レンの上で回ってた。"},{w:"alek",f:"normal",t:"ちがう。「海の上」だ。レンの上じゃない。"},{w:"elly",f:"normal",t:"北は、「亀は、水の底で目をあける」。"},{w:"hero",f:"normal",t:"……とにかく、夜が明けたら、東の海に出る。"}];
CN_DIR.c27_1={"k": "謎", "t": "かけらを合わせる謎・一句につき一つの答え。方角＝西の一句（朝の来る方＝東。夜明けに出る）／場所＝南の一句（海の上の鳥の輪の下）／開け方＝北の一句（水の底の目があく）・覚えること＝聞いた言葉を組み合わせる。まちがえても、選び直せる。"};
CN_SC.c27_2=[{w:null,t:"漁師の船で、東へ。水平線が、白くなってきた。"},{w:null,t:"日がのぼった。その時、沖の一か所に、海鳥がたくさん集まってきた。"},{w:null,t:"海鳥たちは、同じ場所の上を、ぐるぐると回りはじめた。"},{w:"elly",f:"surprised",t:"……輪を描いてる。"},{w:"alek",f:"normal",t:"あれだ。"},{w:null,t:"船を近づける。のぞきこむと、すき通った水の底に、丸い大きな石が見えた。"},{w:null,t:"石のまん中に、ひびのような線。……閉じた、目の形だった。"},{w:"lifa",f:"surprised",t:"亀の、目……。"},{w:"hao",f:"normal",t:"……で、どうやってあけるんだ。"},{w:null,t:"セイリュが、ヤマトの腕の中で、首を持ち上げた。"}];
CN_SC.c27_3=[{w:"hero",f:"normal",t:"……セイリュ？"},{w:null,t:"セイリュは、水の底の石を見て、小さく鳴いた。それから、もう一度、大きく。"},{w:null,t:"水の底の石が、ゆっくりと、まぶたをあけるように割れた。"},{w:null,t:"割れ目から、白い泡が立ちのぼる。海の水が、左右に分かれていく。"},{w:null,t:"分かれた海の底に、石の道が、遠くの大きな岩へ続いていた。"},{w:"elly",f:"surprised",t:"……門だ。"},{w:"hao",f:"surprised",t:"師匠の口伝、ほんとだったのか……。"},{w:"partner",t:"……下から、でかい寝息がする。"}];
CN_SC.c27_4=[{w:null,t:"その時、セイリュの首のチップが、赤く光った。"},{w:null,t:"チップから、低い男の声がした。静かな声だった。"},{w:"x",n:"低い声",t:"……戻れ。"},{w:null,t:"セイリュの体が、びくりとかたまった。"},{w:"hero",f:"surprised",t:"……今の、だれの声だ。"},{w:"lifa",f:"serious",t:"チップに、直接……。送り手を見る。"},{w:null,t:"リーファの端末に、合図の送り手が出た。「アドリアン」"},{w:"alek",f:"serious",t:"……書類の名前だ。"},{w:null,t:"セイリュは、ヤマトの腕の中で、沖の方を見ていた。"},{w:null,t:"第27話　おわり"}];
CN_SC.c28_1=[{w:null,t:"第28話　呼ばれる"},{w:null,t:"分かれた海の底の石の道を、五人は走った。両側は、高い水の壁。"},{w:null,t:"セイリュは、ヤマトの腕の中で、ずっと沖の方を見ていた。"},{w:"hero",f:"normal",t:"セイリュ。こっち。"},{w:null,t:"セイリュは、ふり向かなかった。"},{w:"elly",f:"sad",t:"……聞こえてないの？"},{w:"lifa",f:"serious",t:"合図が、ずっと入ってる。止められない。"},{w:null,t:"水の壁の向こうに、大きな黒い船の影が見えた。ゼロデイの印。"},{w:"hao",f:"angry",t:"船ごと来たのかよ。"}];
CN_SC.c28_2=[{w:null,t:"黒い船から、手下たちが、石の道の上に下りてきた。"},{w:"x",n:"ゼロデイの手下",t:"竜をよこせ。上からの命令だ。今度の上は、本当に上だぞ。"},{w:"alek",f:"normal",t:"連戦になる。一戦ごとに、手持ちを見ろ。"},{w:"hero",f:"serious",t:"……エンジュ、行くぞ。"}];
CN_DIR.c28_2={"k": "勝負", "t": "ゼロデイの船の見張り・盤＝海の底の石の道（荒地と水辺）・覚えること＝ボスの連戦。一戦目で全部の力を出しきらない。けがした子は、次の勝負で休ませる。"};
CN_SC.c28_3w=[{w:"x",n:"ゼロデイの手下",t:"くそっ……。でも、もう遅い。"},{w:null,t:"セイリュが、自分からヤマトの腕をすりぬけた。"},{w:"hero",f:"surprised",t:"セイリュ！"},{w:null,t:"セイリュは、石の道を、黒い船の方へ、ふらふらと歩いていった。"}];
CN_SC.c28_3l=[{w:"x",n:"ゼロデイの手下",t:"よし、竜を——"},{w:null,t:"手下が手をのばした時、セイリュが、自分からヤマトの腕をすりぬけた。"},{w:"hero",f:"surprised",t:"セイリュ！"},{w:null,t:"セイリュは、石の道を、黒い船の方へ、ふらふらと歩いていった。"}];
CN_SC.c28_4=[{w:null,t:"その前に、レンが立っていた。足もとに、黒い角の子。頭の上を、火の鳥。"},{w:"dimi",t:"……竜は、こっちへ来る。"},{w:"hero",f:"angry",t:"来てない。呼ばれてるだけだ。"},{w:"dimi",t:"同じことだ。"},{w:null,t:"セイリュは、レンの横を通りすぎて、船へ向かっていく。レンは、止めなかった。"},{w:"alek",f:"serious",t:"ヤマト。二戦目だ。さっきけがした子は、下げろ。"},{w:"hero",f:"normal",t:"コグリフ。アレクの子と、行け。"},{w:null,t:"コグリフとユキマダラが、並んで跳んだ。氷の脚の、光る馬になった。"},{w:"dimi",t:"……また、ちがうのか。"}];
CN_DIR.c28_4={"k": "勝負", "t": "レン（黒い角の子と、カブトムシの子＝ヘラツノ）・盤＝海の底の石の道・覚えること＝ボスの連戦の二戦目。前の勝負でけがした子を下げて、休ませた子を前に。黒い角の子は、まわりの子を守らない（第19話）。融合は、ヤマトのコグリフ（グリフォ）とアレクのユキマダラでスレイプニア（光）。"};
CN_SC.c28_5w=[{w:null,t:"黒い角の子が、石の道にひざをついた。レンは、何も言わなかった。"},{w:null,t:"顔を上げると、セイリュは、もう黒い船の下に立っていた。"},{w:"hero",f:"serious",t:"セイリュ！"},{w:null,t:"セイリュは、一度も、ふり向かなかった。"},{w:null,t:"セイリュの目は、黒い船の上の、だれかを見上げていた。"},{w:null,t:"第28話　おわり"}];
CN_SC.c28_5l=[{w:null,t:"黒い角の子の角が、エンジュをはじいた。エンジュは、すぐに起き上がった。"},{w:"partner",t:"……まだ、やれる。"},{w:null,t:"顔を上げると、セイリュは、もう黒い船の下に立っていた。"},{w:"hero",f:"serious",t:"セイリュ！"},{w:null,t:"セイリュは、一度も、ふり向かなかった。"},{w:null,t:"セイリュの目は、黒い船の上の、だれかを見上げていた。"},{w:null,t:"第28話　おわり"}];
CN_SC.c29_1=[{w:null,t:"第29話　自分で立つ"},{w:null,t:"黒い船のはしごの下で、セイリュが首を上げていた。チップが、赤く光っている。"},{w:"x",n:"アドリアンの声",t:"……来い。"},{w:null,t:"ヤマトは、走ってきて、セイリュの一歩手前で止まった。手は、のばさなかった。"},{w:null,t:"それから、石の道に、どすんと座った。エンジュも、横に座った。"},{w:"elly",f:"surprised",t:"……ヤマト？"},{w:"hero",f:"normal",t:"……待つ。"},{w:"alek",f:"normal",t:"……そうか。"},{w:null,t:"セイリュは、船を見上げた。それから、ふり返って、座っているヤマトを見た。"},{w:null,t:"もう一度、船。もう一度、ヤマト。"},{w:null,t:"セイリュは、石の道に、ぐっと頭を押しつけた。体が、ふるえている。"},{w:null,t:"チップの赤い光が、ちかちかと乱れた。"},{w:null,t:"セイリュが、頭を上げた。四本の足で、まっすぐ立った。"}];
CN_SC.c29_2=[{w:null,t:"セイリュの体が、白い光に包まれた。光の中で、体が長くのびていく。"},{w:null,t:"光がほどけると、そこにいたのは、海の色の大きな竜だった。"},{w:"hao",f:"surprised",t:"……セイリュウ。"},{w:"lifa",f:"surprised",t:"設計図に、ない形……。"},{w:"x",n:"アドリアンの声",t:"……戻れ。"},{w:null,t:"竜は、船の方を見なかった。ヤマトの前に、頭を下げた。"},{w:"hero",f:"normal",t:"……でかくなったな。"},{w:null,t:"竜は、ヤマトの上着のすそを、そっとくわえた。"},{w:"hero",f:"normal",t:"……くすぐったい。"}];
CN_SC.c29_3=[{w:null,t:"黒い船の横腹が開いた。飛ぶ機械と、首の赤く光る子たちが、次々に下りてくる。"},{w:"x",n:"ゼロデイの手下",t:"竜をつかまえろ！　進化したなら、なおさらだ！"},{w:null,t:"石の道の向こうで、レンが黒い角の子を見下ろしていた。"},{w:"x",n:"ゼロデイの手下",t:"レン！　その黒いのを出せ！　取り引きだろ！"},{w:null,t:"レンは、黒い角の子の首輪から、小さな部品を一つ外した。"},{w:null,t:"それから、黒い角の子の背中を、船の方へ押した。"},{w:"dimi",t:"……いらない。"},{w:null,t:"黒い角の子は、とまどったように、船の方へ歩いていった。"},{w:"x",n:"ゼロデイの手下",t:"お、おい！　取り引きはどうなる！"},{w:null,t:"レンは答えずに、外した部品を投げた。"},{w:null,t:"部品は、まっすぐリーファの手に飛んできた。"},{w:"lifa",f:"surprised",t:"……なにこれ。"},{w:"dimi",t:"……そいつの首輪の鍵。竜のも、同じだ。"},{w:null,t:"その時、空から火の鳥が下りてきた。レンの横の石の上に、羽をたたんで、並んだ。"},{w:"dimi",t:"……今ごろかよ。"}];
CN_SC.c29_4=[{w:"alek",f:"serious",t:"リーファ、鍵、使えるか。"},{w:"lifa",f:"serious",t:"時間をちょうだい。"},{w:"hao",f:"normal",t:"時間かせぎなら、得意だ。"},{w:"hero",f:"serious",t:"セイリュウ、行けるか。"},{w:null,t:"竜は、低く一声鳴いた。"}];
CN_DIR.c29_4={"k": "勝負", "t": "ゼロデイの船の子たち・盤＝ひらいた海の底（水辺と荒地）・覚えること＝三段目の進化（ふるさとで）。セイリュウ（竜・三段目）が味方に入る。竜は荒地で攻撃が上がる。レンのカブトムシの子（ヘラツノ）と朱雀も、この勝負だけ味方に入る。"};
CN_SC.c29_5w=[{w:null,t:"ゼロデイの子たちは、一体ずつ、船の中へ逃げもどっていった。"},{w:null,t:"戦いが終わると、竜の体は、ゆっくり、もとのセイリュの姿にもどった。"},{w:"lifa",f:"serious",t:"……鍵、入った。外すわよ。"},{w:null,t:"リーファが端末を押した。竜の首のチップが、ぱちんと外れて、石の上に落ちた。"},{w:null,t:"チップの赤い光は、もう、つかなかった。"}];
CN_SC.c29_5l=[{w:null,t:"押しこまれた時、火の鳥が大きく羽ばたいた。ゼロデイの子たちが、下がった。"},{w:null,t:"戦いが終わると、竜の体は、ゆっくり、もとのセイリュの姿にもどった。"},{w:"lifa",f:"serious",t:"……鍵、入った。外すわよ。"},{w:null,t:"リーファが端末を押した。竜の首のチップが、ぱちんと外れて、石の上に落ちた。"},{w:null,t:"チップの赤い光は、もう、つかなかった。"}];
CN_SC.c29_6=[{w:null,t:"船の中から、さっきの低い声が、もう一度だけ聞こえかけた。"},{w:"x",n:"アドリアンの声",t:"……"},{w:null,t:"声は、それきりだった。通信の切れる、小さな音がした。"},{w:null,t:"黒い船は、ゆっくり向きを変えて、沖へ出ていった。黒い角の子を乗せて。"},{w:null,t:"火の鳥は、レンの頭の上を一回だけ回ると、南の空へ飛んでいった。"},{w:"dimi",t:"……。"},{w:null,t:"レンは、何も言わずに、反対の方へ歩きだした。"},{w:"hero",f:"normal",t:"……あいつ、鍵、投げてった。"},{w:"partner",t:"投げ方は、へただった。"},{w:null,t:"第29話　おわり"}];
CN_SC.c30_1=[{w:null,t:"第30話　青龍の岩"},{w:null,t:"海の底の石の道の先。大きな岩が、海の上に、まっすぐ立っていた。"},{w:null,t:"岩に見えたのは、とぐろを巻いて眠る、大きな青い竜だった。"},{w:"hao",f:"surprised",t:"……青龍だ。年寄りの、セイリュウ。"},{w:"elly",f:"normal",t:"ハオ、呼ぶ所。"},{w:"hao",f:"normal",t:"……ああ。"},{w:null,t:"ハオが唱え、エリーが「ほー、ほー」と重ねた。"},{w:null,t:"年寄りのセイリュウが、まぶたをあけた。海の色の目が、セイリュを見た。"},{w:null,t:"古い言葉で、一言。"},{w:"hao",f:"normal",t:"……「来たか」。"},{w:null,t:"セイリュは、年寄りのセイリュウの横へ泳いでいき、そのとぐろの中に、体を入れた。"},{w:"partner",t:"……あそこが、寝床か。"},{w:"lifa",f:"smile",t:"熱も、もうない。"}];
CN_SC.c30_2=[{w:null,t:"セイリュが、もう一度、ヤマトの所へ戻ってきた。"},{w:null,t:"ヤマトの上着のすそを、そっとくわえた。"},{w:"hero",f:"normal",t:"……のびるって。"},{w:null,t:"セイリュは、くわえたまま、はなさなかった。"},{w:null,t:"年寄りのセイリュウが、とぐろの中から、それを見ていた。"},{w:"hao",f:"normal",t:"……行けって顔してる。たぶん。"},{w:"lifa",f:"normal",t:"チップは、もうないの。"},{w:null,t:"セイリュは、すそをくわえたまま、ヤマトの背中にのぼった。"},{w:"hero",f:"normal",t:"……重い。"},{w:"partner",t:"……また、ふえた。"},{w:null,t:"年寄りのセイリュウは、目を閉じた。"},{w:"hero",f:"normal",t:"……上着、よだれだらけ。"}];
CN_SC.c30_3=[{w:null,t:"浜まで戻ると、漁師の船が待っていた。"},{w:"hao",f:"normal",t:"おれは、道場に帰る。師匠に、口伝の話をする。"},{w:"lifa",f:"normal",t:"わたしは、研究所に戻る。第七棟の記録、全部、手で調べ直す。"},{w:"hao",f:"smile",t:"手で？　AIじゃなくて？"},{w:"lifa",f:"smile",t:"両方。"},{w:"hao",f:"normal",t:"……帰り、竹の村まで送ってやろうか。"},{w:"lifa",f:"normal",t:"バスで帰れる。"},{w:"hao",f:"angry",t:"……だよな。"},{w:"elly",f:"smile",t:"この二人、ずっとこう。"},{w:null,t:"ハオとリーファは、それぞれの方へ歩いていった。三回、ふり返って言い合いながら。"}];
CN_SC.c30_4=[{w:null,t:"夕方。三人とセイリュは、浜から、海の上の年寄りのセイリュウを見ていた。"},{w:null,t:"年寄りのセイリュウが、こちらへ首をのばした。大きな目に、何かが映っている。"},{w:null,t:"砂の色の国。一本の大きな川。"},{w:null,t:"川をせき止める、灰色の高い壁。"},{w:null,t:"壁の向こうの、水の底。沈んだ村の屋根が、ゆらゆらと見えた。"},{w:"hero",f:"surprised",t:"……今の。"},{w:"partner",t:"……下で、何か寝てた。"},{w:null,t:"年寄りのセイリュウは、目を閉じた。海は、静かになった。"},{w:null,t:"第30話　おわり　中国編　おわり"}];
